const FIELDS = RESP.fields;
const ROWS = RESP.rows;
const FIDX = {}; FIELDS.forEach((f,i) => FIDX[f]=i);
function val(row, field) {
  // Derived profile/filter indicators used across the dashboard.
  if (field === 'visit_nearterm') {
    const v = row[FIDX['e4_visit_plans']];
    if (v === null || v === undefined) return null;
    return ['soon','within_year','within_3y'].includes(v) ? 1 : 0;
  }
  if (field === 'visit_nointent') {
    const v = row[FIDX['e4_visit_plans']];
    if (v === null || v === undefined) return null;
    return v === 'no' ? 1 : 0;
  }
  if (field === 'willing_watch') {
    const v = row[FIDX['c15']];
    if (v === null || v === undefined) return null;
    if (['def_would','prob_would'].includes(v)) return 'yes';
    if (v === 'notsure') return 'notsure';
    if (['prob_not','def_not'].includes(v)) return 'no';
    return null;
  }
  if (field === 'influential_business_investment') {
    const b = row[FIDX['f1_biz']], i = row[FIDX['f1_invest']];
    if (b === null && i === null) return null;
    return (b === 1 || i === 1) ? 1 : 0;
  }
  return row[FIDX[field]];
}

const SCREENER_ROWS = SCREENER_ROWS_DATA.rows;
const SCREENER_FIDX = {}; SCREENER_ROWS_DATA.fields.forEach((f,i) => SCREENER_FIDX[f]=i);
function sval(row, field) { const i = SCREENER_FIDX[field]; return i===undefined ? undefined : row[i]; }

