function filterSummaryParts(state) {
  const parts=[];
  FILTER_DEFS.forEach(f=>{
    const sel=state[f.key];
    if(f.type==='multi' && sel && sel.length){
      const vals=sel.map(v=>(f.names&&f.names[v])||v);
      parts.push(`${f.label}: ${vals.join(', ')}`);
    } else if(f.type==='tri' && sel!=='any') {
      parts.push(`${f.label}: ${sel==='yes'?'Yes':'No'}`);
    } else if(f.type==='willingness' && sel && sel.length) {
      const labels = sel.map(v => v==='yes' ? 'Yes' : (v==='notsure' ? 'Not sure' : 'No'));
      parts.push(`${f.label}: ${labels.join(', ')}`);
    } else if(f.type==='profile' && sel && sel!=='any') {
      const opt=(f.options||[]).find(o=>o[0]===sel);
      parts.push(`${f.label}: ${opt ? opt[1] : sel}`);
    }
  });
  return parts;
}
function audienceSummaryGroup(label, parts, n, side, warning) {
  const chips = parts.length
    ? parts.map(x=>`<span class="summary-filter-chip ${side}" title="${x.replace(/&/g,'&amp;').replace(/"/g,'&quot;')}">${x}</span>`).join('')
    : `<span class="summary-filter-chip ${side}">All respondents</span>`;
  const reset = parts.length
    ? `<button type="button" class="summary-reset" data-reset-audience="${side}" title="Reset to everyone" aria-label="Reset ${label} to everyone"><span class="summary-reset-icon" aria-hidden="true">&#8634;</span><span>Reset to everyone</span></button>`
    : '';
  return `<div class="audience-summary-group"><span class="summary-label">${label}</span>${chips}<span class="summary-base-chip ${side}">n=${n}</span>${warning?`<span class="sample-warning">${warning}</span>`:''}${reset}</div>`;
}
function renderAudienceSummary(rowsA, rowsB, isScreener) {
  const el=document.getElementById('audienceSummary');
  const ws=document.getElementById('audienceWorkspace');
  if(!el||!ws) return;
  ws.style.display=isScreener?'none':'';
  if(isScreener) return;
  const pA=filterSummaryParts(filterA);
  const pB=filterSummaryParts(filterB);
  const warnA=rowsA.length<50?'Very small base':rowsA.length<100?'Small base':'';
  const warnB=compareOn?(rowsB.length<50?'Very small base':rowsB.length<100?'Small base':''):'';
  el.innerHTML = audienceSummaryGroup('Audience 1', pA, rowsA.length, 'A', warnA) +
    (compareOn ? audienceSummaryGroup('Audience 2', pB, rowsB.length, 'B', warnB) : '');
}
