function fieldMarketEligible(r, field, valFn){
  valFn = valFn || val;
  const markets = FIELD_ELIGIBLE_COUNTRIES[field];
  if(markets && !markets.includes(valFn(r,'country'))) return false;
  const v = valFn(r,field);
  return v===0 || v===1;
}
function fieldEligibleRows(rows, field, valFn){
  return rows.filter(r=>fieldMarketEligible(r,field,valFn));
}

// v1514 categorical ordering consistency: ordered/profile dimensions preserve defined category order across dashboard.
// ---------------- AGGREGATION ----------------
function pctFlag(rows, field, valFn) {
  valFn = valFn || val;
  const elig = fieldEligibleRows(rows,field,valFn);
  if(!elig.length) return null;
  const hit = elig.filter(r=>valFn(r,field)===1).length;
  return Math.round(hit/elig.length*1000)/10;
}
function catDist(rows, field, valFn) {
  valFn = valFn || val;
  let n=0; const counts = {};
  rows.forEach(r => { const v = valFn(r,field); if (v!==null && v!==undefined) { n++; counts[v]=(counts[v]||0)+1; } });
  const out = {};
  Object.keys(counts).forEach(k => out[k] = Math.round(counts[k]/n*1000)/10);
  return { dist: out, n };
}

