const DRILL_COUNTRY_NAMES = { AU:'Australia', CA:'Canada', CN:'China', FR:'France', IN:'India', KR:'South Korea', SG:'Singapore', UK:'United Kingdom', US:'United States' };
function flagFor(code) { return ''; }
const DRILL_GENDER_NAMES = { M:'Male', F:'Female', O:'Other / prefer not to say' };
const DRILL_INCOME_NAMES = { L:'Lower income', M:'Middle income', H:'Higher income' };

function catCount(rows, field, cat, valFn) {
  valFn = valFn || val;
  let n=0, count=0;
  rows.forEach(r => { const v = valFn(r,field); if (v!==null && v!==undefined) { n++; if (v===cat) count++; } });
  return { n, count };
}
function flagCount(rows, field, valFn) {
  valFn = valFn || val;
  const elig = fieldEligibleRows(rows,field,valFn);
  return { n:elig.length, count:elig.filter(r=>valFn(r,field)===1).length };
}
function computeIndexSig(subN, subCount, univN, univCount) {
  const restN = univN - subN;
  const restCount = univCount - subCount;
  const subP = subN>0 ? subCount/subN : null;
  const univP = univN>0 ? univCount/univN : null;
  const index = (subP!==null && univP) ? Math.round(subP/univP*100) : null;
  let sig = false;
  if (subN>0 && restN>0 && univN>0) {
    const restP = restCount/restN;
    const pooledP = univCount/univN;
    const se = Math.sqrt(pooledP*(1-pooledP)*(1/subN + 1/restN));
    if (se>0) sig = Math.abs((subP-restP)/se) >= 1.96;
  }
  return { index, sig };
}
function indexBadge(index, sig) {
  if (index===null || !isFinite(index)) return '<span class="idxval">idx n/a</span>';
  const dir = index < 100 ? 'neg' : 'pos';
  const cls = 'idxval' + (sig ? ` sig ${dir}` : '');
  const sigDir = index >= 100 ? 'high' : 'low';
  const sigText = sigDir==='high' ? '▲' : '▼';
  const sigTitle = currentLang === 'vi'
    ? `${sigDir==='high'?'Cao hơn':'Thấp hơn'} phần còn lại có ý nghĩa thống kê ở mức tin cậy 95%`
    : `Significantly ${sigDir==='high'?'higher':'lower'} than the rest of the comparison universe at 95% confidence`;
  return `<span class="${cls}">idx ${index}</span>${sig?`<span class="sigbadge drill ${sigDir}" title="${sigTitle}" aria-label="${sigTitle}">${sigText}</span>`:''}`;
}

function drillCatRow(label, subRows, univRows, field, cat, nameMap, valFn) {
  const s = catCount(subRows, field, cat, valFn);
  const u = catCount(univRows, field, cat, valFn);
  const subV = s.n>0 ? s.count/s.n*100 : 0;
  const univV = u.n>0 ? u.count/u.n*100 : 0;
  const { index, sig } = computeIndexSig(s.n, s.count, u.n, u.count);
  const row = document.createElement('div'); row.className = 'barrow';
  row.innerHTML = `<div class="barlabel">${(nameMap && nameMap[cat]) || cat}</div>
    <div class="bartrack">
      <div style="position:absolute;left:0;top:0;height:9px;border-radius:3px;background:var(--drill);width:${subV}%"></div>
      <div style="position:absolute;left:0;bottom:0;height:9px;border-radius:3px;background:var(--text-muted);width:${univV}%"></div>
    </div>
    <div class="barval">${subV.toFixed(0)}% / ${univV.toFixed(0)}% ${indexBadge(index, sig)}</div>`;
  return row;
}

function drillFlagRow(label, subRows, univRows, field, valFn) {
  const s = flagCount(subRows, field, valFn);
  const u = flagCount(univRows, field, valFn);
  const subV = s.n>0 ? s.count/s.n*100 : null;
  const univV = u.n>0 ? u.count/u.n*100 : null;
  const { index, sig } = computeIndexSig(s.n, s.count, u.n, u.count);
  const row = document.createElement('div'); row.className = 'barrow';
  row.innerHTML = `<div class="barlabel">${label}</div>
    <div class="bartrack">
      <div style="position:absolute;left:0;top:0;height:9px;border-radius:3px;background:var(--drill);width:${subV||0}%"></div>
      <div style="position:absolute;left:0;bottom:0;height:9px;border-radius:3px;background:var(--text-muted);width:${univV||0}%"></div>
    </div>
    <div class="barval">${subV!==null?subV.toFixed(0)+'%':'n/a'} / ${univV!==null?univV.toFixed(0)+'%':'n/a'} ${indexBadge(index, sig)}</div>`;
  return row;
}

