function twoPropSig(countA, nA, countB, nB) {
  if (!nA || !nB) return false;
  const pA = countA/nA, pB = countB/nB;
  const pooled = (countA+countB)/(nA+nB);
  const se = Math.sqrt(pooled*(1-pooled)*(1/nA+1/nB));
  if (!se) return false;
  return Math.abs((pA-pB)/se) >= 1.96;
}
function sigSuffix(sig, a, b, tooltip) {
  if (!sig || a===null || a===undefined || b===null || b===undefined || a===b) return '';
  const winner = a > b ? 'A' : 'B';
  const loser = winner==='A' ? 'B' : 'A';
  const cls = winner.toLowerCase();
  const title = currentLang === 'vi'
    ? `Đối tượng ${winner} cao hơn Đối tượng ${loser} có ý nghĩa thống kê ở mức tin cậy 95%`
    : (tooltip || `Audience ${winner} is significantly higher than Audience ${loser} at 95% confidence`);
  return `<span class="sigbadge ${cls}" title="${title}" aria-label="${title}">▲</span>`;
}


function displayCountryName(label) {
  if (currentLang !== 'vi') return label;
  const map = {
    'Vietnam':'Việt Nam','Japan':'Nhật Bản','Thailand':'Thái Lan','Mexico':'Mexico','Poland':'Ba Lan',
    'India':'Ấn Độ','Indonesia':'Indonesia','Kenya':'Kenya','Australia':'Úc','Canada':'Canada','China':'Trung Quốc',
    'France':'Pháp','South Korea':'Hàn Quốc','S. Korea':'Hàn Quốc','Singapore':'Singapore',
    'United Kingdom':'Vương quốc Anh','UK':'Vương quốc Anh','United States':'Hoa Kỳ','US':'Hoa Kỳ'
  };
  return map[label] || label;
}
function sigNamedSuffix(sig, firstValue, secondValue, firstLabel, secondLabel, firstClass, secondClass, tooltip) {
  if (!sig || firstValue===null || firstValue===undefined || secondValue===null || secondValue===undefined || firstValue===secondValue) return '';
  const firstWins = firstValue > secondValue;
  const rawLabel = firstWins ? firstLabel : secondLabel;
  const rawOther = firstWins ? secondLabel : firstLabel;
  const label = displayCountryName(rawLabel);
  const other = displayCountryName(rawOther);
  const cls = firstWins ? firstClass : secondClass;
  const title = currentLang === 'vi'
    ? `${label} cao hơn ${other} có ý nghĩa thống kê ở mức tin cậy 95%`
    : (tooltip || `${label} is significantly higher than ${other} at 95% confidence`);
  return `<span class="sigbadge ${cls}" title="${title}" aria-label="${title}">▲</span>`;
}

function eligibleRows(rows, field, valFn) {
  valFn = valFn || val;
  if(FIELD_ELIGIBLE_COUNTRIES[field]) return fieldEligibleRows(rows,field,valFn);
  return rows.filter(r => { const v = valFn(r, field); return v !== null && v !== undefined; });
}

function makeClickable(rowEl, universeRows, predicateFn, label, isScreenerPop) {
  if (!universeRows || typeof predicateFn !== 'function') return;
  const subRows = universeRows.filter(predicateFn);
  rowEl.classList.add('clickable');
  const answerN = subRows.length;
  const baseN = universeRows.length;
  const nText = `Answer n = ${answerN.toLocaleString()} / Base n = ${baseN.toLocaleString()}`;
  rowEl.title = nText;
  const track = rowEl.querySelector('.bartrack');
  if (track) track.title = nText;
  const labelEl = rowEl.querySelector('.barlabel');
  if (labelEl) labelEl.title = nText;
  rowEl.onclick = () => {
    showDrilldown(subRows, universeRows, label, !!isScreenerPop);
  };
}

function makeMetricClickable(el, universeRows, predicateFn, label, isScreenerPop) {
  if (!el || !universeRows || typeof predicateFn !== 'function') return;
  const subRows = universeRows.filter(predicateFn);
  const nText = `Answer n = ${subRows.length.toLocaleString()} / Base n = ${universeRows.length.toLocaleString()}`;
  el.classList.add('metric-click');
  el.title = nText;
  el.onclick = (ev) => {
    ev.stopPropagation();
    showDrilldown(subRows, universeRows, label, !!isScreenerPop);
  };
}


function decorateQuickviewIcons() {
  document.querySelectorAll('.quickview[data-section]').forEach(btn => {
    if (btn.querySelector('.qicon')) return;
    const sec = SECTIONS[btn.dataset.section];
    if (!sec || !sec.icon) return;
    const t = btn.textContent;
    btn.innerHTML = `<span class="qicon">${sec.icon}</span><span>${t}</span>`;
  });
}

