function buildNav() {
  const el = document.getElementById('navList');
  el.innerHTML = '';
  NAV_GROUPS.forEach(([group, keys]) => {
    const gh=document.createElement('div'); gh.className='navgroup'; gh.textContent=group; el.appendChild(gh);
    keys.forEach(key=>{
      if(!SECTIONS[key]) return;
      const item = document.createElement('div');
      item.className = 'navitem' + (key===currentSection ? ' active':'');
      const icon = SECTIONS[key].icon || '';
      item.innerHTML = `<span class="navicon">${icon}</span><span>${SECTIONS[key].label}</span>`;
      item.onclick = () => { currentSection = key; currentModule = Object.keys(SECTIONS[key].modules)[0]; render(); };
      el.appendChild(item);
    });
  });
}

function buildFilterPanel(containerId, state, cardClass) {
  const el = document.getElementById(containerId);
  el.innerHTML = '';
  FILTER_GROUPS.forEach(g => {
    const sec = document.createElement('div');
    sec.className = `filtersection ${g.key}`;
    const title = document.createElement('div');
    title.className = 'filtersection-title';
    title.textContent = g.label;
    sec.appendChild(title);
    const grid = document.createElement('div');
    grid.className = 'filtersection-grid';
    FILTER_DEFS.filter(f => f.group===g.key).forEach(f => {
      const grp = document.createElement('div');
      grp.className = 'filtergroup';
      grp.dataset.filterKey = f.key;
      if (f.key === 'segment') grp.classList.add('segment-filter');
      const lbl = document.createElement('label');
      lbl.className = 'flabel';
      lbl.textContent = f.label;
      grp.appendChild(lbl);
      if (f.type === 'multi') {
        const cs = document.createElement('div'); cs.className='chipset';
        if (f.exclusiveTotal) {
          const totalChip = document.createElement('div');
          totalChip.className = 'chip' + (state[f.key].length===0 ? ' sel':'');
          totalChip.textContent = 'Total';
          totalChip.onclick = () => { state[f.key] = []; render(); };
          cs.appendChild(totalChip);
        }
        f.options.forEach(opt => {
          const chip = document.createElement('div');
          chip.className = 'chip' + (state[f.key].includes(opt) ? ' sel':'');
          chip.textContent = (f.names && f.names[opt]) || opt;
          chip.onclick = () => {
            const idx = state[f.key].indexOf(opt);
            if (idx>=0) state[f.key].splice(idx,1); else state[f.key].push(opt);
            render();
          };
          cs.appendChild(chip);
        });
        grp.appendChild(cs);
      } else if (f.type === 'willingness') {
        const ts = document.createElement('div'); ts.className='triset';
        const current = Array.isArray(state[f.key]) ? state[f.key] : [];
        [['any','Any'],['yes','Yes'],['notsure','Not sure'],['no','No']].forEach(([v,l]) => {
          const t = document.createElement('div');
          const selected = v === 'any' ? current.length === 0 : current.includes(v);
          t.className = 'tri' + (selected ? ' sel':'');
          t.textContent = l;
          t.onclick = () => {
            if (v === 'any') {
              state[f.key] = [];
            } else {
              const arr = Array.isArray(state[f.key]) ? [...state[f.key]] : [];
              const idx = arr.indexOf(v);
              if (idx >= 0) arr.splice(idx,1); else arr.push(v);
              state[f.key] = arr;
            }
            render();
          };
          ts.appendChild(t);
        });
        grp.appendChild(ts);
      } else if (f.type === 'profile') {
        const cs = document.createElement('div'); cs.className='chipset';
        f.options.forEach(([v,l]) => {
          const chip = document.createElement('div');
          chip.className = 'chip' + (state[f.key]===v ? ' sel':'');
          chip.textContent = l;
          chip.onclick = () => { state[f.key] = v; render(); };
          cs.appendChild(chip);
        });
        grp.appendChild(cs);
      } else {
        const ts = document.createElement('div'); ts.className='triset';
        [['any','Any'],['yes','Yes'],['no','No']].forEach(([v,l]) => {
          const t = document.createElement('div');
          t.className = 'tri' + (state[f.key]===v ? ' sel':'');
          t.textContent = l;
          t.onclick = () => { state[f.key] = v; render(); };
          ts.appendChild(t);
        });
        grp.appendChild(ts);
      }
      grid.appendChild(grp);
    });
    sec.appendChild(grid);
    el.appendChild(sec);
  });
}
function baseNFlag(rows, field) {
  return fieldEligibleRows(rows,field).length;
}

function renderFlagsModule(mod, rowsA, rowsB) {
  const vizArea = document.getElementById('vizArea');
  const hasSummary = !!mod.summaryBinary;
  const wrap = hasSummary ? document.createElement('div') : null;
  const barsCol = hasSummary ? document.createElement('div') : null;
  if (hasSummary) { wrap.className='scalewrap'; barsCol.className='scalebars'; }
  const targetEl = hasSummary ? barsCol : vizArea;

  const data = mod.fields.map(([field,label]) => ({
    field, label, a: pctFlag(rowsA, field), b: compareOn ? pctFlag(rowsB, field) : null,
  }));
  if (!mod.noSort) data.sort((x,y) => (y.a||0)-(x.a||0));
  const maxV = 100;
  data.forEach(d => {
    const row = document.createElement('div'); row.className='barrow';
    if (compareOn) {
      const cA = flagCount(rowsA, d.field), cB = flagCount(rowsB, d.field);
      const sig = twoPropSig(cA.count, cA.n, cB.count, cB.n);
      row.innerHTML = `<div class="barlabel">${d.label}</div>
        <div class="bartrack">
          <div class="barfillA" style="width:${(d.a/maxV*100).toFixed(1)}%"></div>
          <div class="barfillB" style="width:${(d.b/maxV*100).toFixed(1)}%"></div>
        </div>
        <div class="barval"><div class="cmpvals"><span class="vA">A ${d.a!==null?d.a.toFixed(0)+'%':'n/a'}</span><span class="vB">B ${d.b!==null?d.b.toFixed(0)+'%':'n/a'}</span></div>${sigSuffix(sig, d.a, d.b)}</div>`;
      row.title = `${d.label} · Audience A: ${cA.count}/${cA.n} (${d.a!==null?d.a.toFixed(1)+'%':'n/a'}) · Audience B: ${cB.count}/${cB.n} (${d.b!==null?d.b.toFixed(1)+'%':'n/a'})`;
    } else {
      const cA = flagCount(rowsA, d.field);
      row.innerHTML = `<div class="barlabel">${d.label}</div>
        <div class="bartrack"><div class="barfillSingle" style="width:${(d.a/maxV*100).toFixed(1)}%"></div></div>
        <div class="barval">${d.a!==null?d.a.toFixed(0)+'%':'n/a'}</div>`;
      row.title = `${d.label}: ${cA.count}/${cA.n} eligible respondents (${d.a!==null?d.a.toFixed(1)+'%':'n/a'})`;
      makeClickable(row, eligibleRows(rowsA, d.field), r => val(r, d.field) === 1, d.label);
    }
    targetEl.appendChild(row);
  });

  if (hasSummary) {
    wrap.appendChild(barsCol);
    const cfg = mod.summaryBinary;
    const cA = flagCount(rowsA, cfg.field);
    const posA = cA.n ? cA.count/cA.n*100 : 0;
    const negA = cA.n ? (cA.n-cA.count)/cA.n*100 : 0;
    const cB = compareOn ? flagCount(rowsB, cfg.field) : null;
    const posB = cB && cB.n ? cB.count/cB.n*100 : null;
    const negB = cB && cB.n ? (cB.n-cB.count)/cB.n*100 : null;
    const sqCol=document.createElement('div'); sqCol.className='sqcol';
    const top=document.createElement('div'); top.className='sqtile pos';
    top.innerHTML=`<div class="sqval" style="color:var(--posB)">${posA.toFixed(0)}%</div>${compareOn?`<div class="sqvalB" style="color:var(--posB)">B: ${posB.toFixed(0)}%</div>`:''}<div class="sqlabel">${cfg.topLabel}</div>`;
    const bottom=document.createElement('div'); bottom.className='sqtile neg';
    bottom.innerHTML=`<div class="sqval" style="color:var(--negB)">${negA.toFixed(0)}%</div>${compareOn?`<div class="sqvalB" style="color:var(--negB)">B: ${negB.toFixed(0)}%</div>`:''}<div class="sqlabel">${cfg.bottomLabel}</div>`;
    if (!compareOn) {
      const universe=eligibleRows(rowsA,cfg.field);
      makeClickable(top, universe, r=>val(r,cfg.field)===1, cfg.topLabel);
      makeClickable(bottom, universe, r=>val(r,cfg.field)===0, cfg.bottomLabel);
    } else {
      const universeA=eligibleRows(rowsA,cfg.field), universeB=eligibleRows(rowsB,cfg.field);
      makeMetricClickable(top.querySelector('.sqval'), universeA, r=>val(r,cfg.field)===1, `${cfg.topLabel} · Audience A`);
      makeMetricClickable(top.querySelector('.sqvalB'), universeB, r=>val(r,cfg.field)===1, `${cfg.topLabel} · Audience B`);
      makeMetricClickable(bottom.querySelector('.sqval'), universeA, r=>val(r,cfg.field)===0, `${cfg.bottomLabel} · Audience A`);
      makeMetricClickable(bottom.querySelector('.sqvalB'), universeB, r=>val(r,cfg.field)===0, `${cfg.bottomLabel} · Audience B`);
    }
    sqCol.appendChild(top); sqCol.appendChild(bottom); wrap.appendChild(sqCol); vizArea.appendChild(wrap);
  }

  const baseA = baseNFlag(rowsA, mod.fields[0][0]);
  const baseB = compareOn ? baseNFlag(rowsB, mod.fields[0][0]) : null;
  const isPlatformAvailability = mod.fields.some(([f])=>String(f).startsWith('plat_'));
  const isChannelHomeMarket = mod.fields.some(([f])=>String(f).startsWith('ch_'));
  if(isPlatformAvailability){
    document.getElementById('panelFootnote').textContent = currentLang==='vi'
      ? 'Số mẫu thay đổi theo từng nền tảng tùy theo thị trường có thể sử dụng nền tảng đó. Các nền tảng quốc tế không tính Trung Quốc; các nền tảng riêng của Trung Quốc, Hàn Quốc hoặc Ấn Độ chỉ sử dụng thị trường phù hợp. Di chuột lên từng dòng để xem số người dùng / số mẫu đủ điều kiện.'
      : 'Base varies by platform according to market availability. Global platforms exclude China; China-, Korea- and India-specific platforms use only their eligible market(s). Hover each row to see users n / eligible n.';
  } else if(isChannelHomeMarket){
    document.getElementById('panelFootnote').textContent = currentLang==='vi'
      ? 'Số mẫu thay đổi theo từng kênh: thị trường nội địa của mỗi kênh được loại khỏi phép so sánh quốc tế khi thị trường đó nằm trong khảo sát. Vietnam Today và VTV4 sử dụng toàn bộ nhóm đối tượng đã chọn. Di chuột lên từng dòng để xem số người biết kênh / số mẫu đủ điều kiện.'
      : 'Base varies by channel: each broadcaster’s home market is excluded from the international benchmark where that market is sampled. Vietnam Today and VTV4 use the full selected audience. Hover each row to see aware n / eligible n.';
  } else {
    document.getElementById('panelFootnote').textContent = compareOn
      ? `Base | Audience A: ${baseA}  ·  Audience B: ${baseB}`
      : `Base: ${baseA}${baseA < 100 ? ' (small base, read as directional)' : ''}`;
  }
}


