function socialScaleStats(rows, field) {
  const elig = eligibleRows(rows, field);
  const cats = ['very_interested','interested','somewhat','slightly','not_at_all'];
  const counts = {}; cats.forEach(c=>counts[c]=0);
  elig.forEach(r=>{ const v=val(r,field); if (counts[v]!==undefined) counts[v]++; });
  const pct = {}; cats.forEach(c=>pct[c]=elig.length ? counts[c]/elig.length*100 : 0);
  const topCount=(counts.very_interested||0)+(counts.interested||0);
  const bottomCount=(counts.slightly||0)+(counts.not_at_all||0);
  return { n:elig.length, counts, pct, topCount, bottomCount, topPct:elig.length?topCount/elig.length*100:null, bottomPct:elig.length?bottomCount/elig.length*100:null, elig };
}
const SOCIAL_SCALE_ORDER=['very_interested','interested','somewhat','slightly','not_at_all'];
const SOCIAL_SCALE_LABELS={very_interested:'Very interested',interested:'Interested',somewhat:'Somewhat interested',slightly:'Slightly interested',not_at_all:'Not at all interested'};
const SOCIAL_SCALE_COLORS={very_interested:'#274a93',interested:'#7db2f6',somewhat:'#c9ccd2',slightly:'#f3b9b6',not_at_all:'#d9534f'};
function socialPieGradient(st){
  let c=0, parts=[];
  SOCIAL_SCALE_ORDER.forEach(k=>{ const a=c, b=c+(st.pct[k]||0); parts.push(`${SOCIAL_SCALE_COLORS[k]} ${a.toFixed(2)}% ${b.toFixed(2)}%`); c=b; });
  return `conic-gradient(${parts.join(',')})`;
}
function socialAudiencePanelHtml(st, audLabel, audClass){
  const legend=SOCIAL_SCALE_ORDER.map(k=>`<div class="social-scale-item" data-scale="${k}"><i style="background:${SOCIAL_SCALE_COLORS[k]}"></i><span>${SOCIAL_SCALE_LABELS[k]}</span><strong>${st.n?st.pct[k].toFixed(0)+'%':'n/a'}</strong></div>`).join('');
  return `<div class="social-scale-panel ${audClass}">
    <h5>${audLabel} · Base n=${st.n.toLocaleString()}</h5>
    <div class="social-donut-wrap"><div class="social-donut" style="background:${socialPieGradient(st)}"><div class="social-donut-center"><span class="big">${st.topPct===null?'n/a':st.topPct.toFixed(0)+'%'}</span><span class="small">Top 2 Box</span></div></div></div>
    <div class="social-scale-legend">${legend}</div>
    <div class="social-summary-grid">
      <div class="social-summary-tile top2"><div class="v">${st.topPct===null?'n/a':st.topPct.toFixed(0)+'%'}</div><div class="l">Top 2 Box · Interested + Very interested<br>n=${st.topCount.toLocaleString()}</div></div>
      <div class="social-summary-tile bottom2"><div class="v">${st.bottomPct===null?'n/a':st.bottomPct.toFixed(0)+'%'}</div><div class="l">Bottom 2 Box · Slightly + Not at all interested<br>n=${st.bottomCount.toLocaleString()}</div></div>
    </div>
  </div>`;
}
function attachSocialScaleClicks(panel, st, field, labelPrefix){
  panel.querySelectorAll('.social-scale-item').forEach(el=>{
    const cat=el.dataset.scale;
    makeClickable(el, st.elig, r=>val(r,field)===cat, `${labelPrefix} · ${SOCIAL_SCALE_LABELS[cat]}`);
  });
  makeClickable(panel.querySelector('.top2'), st.elig, r=>['interested','very_interested'].includes(val(r,field)), `${labelPrefix} · Top 2 Box`);
  makeClickable(panel.querySelector('.bottom2'), st.elig, r=>['slightly','not_at_all'].includes(val(r,field)), `${labelPrefix} · Bottom 2 Box`);
}
function renderSocialPostModule(mod, rowsA, rowsB) {
  const vizArea = document.getElementById('vizArea');
  const wrap = document.createElement('div'); wrap.className = 'social-eval';
  const configs=[
    { stim:'post_cultural_top2', scale:'post_cultural_scale' },
    { stim:'post_news_top2', scale:'post_news_scale' }
  ];
  configs.forEach(cfg=>{
    const d=SOCIAL_STIMULI[cfg.stim]; if(!d) return;
    const a=socialScaleStats(rowsA,cfg.scale), b=compareOn?socialScaleStats(rowsB,cfg.scale):null;
    const card=document.createElement('div'); card.className='social-eval-card';
    card.innerHTML=`<div class="social-eval-head"><div class="social-eval-postno">${d.postNo}</div><div class="social-eval-title">${d.title}</div></div>
      <div class="social-eval-body ${compareOn?'is-compare':''}"><div class="social-eval-postimg"><img src="${d.src}" alt="${d.title}"></div><div class="social-sentiment"><h4>Interest after exposure</h4>
      <div class="social-scale-auds ${compareOn?'compare':''}">${socialAudiencePanelHtml(a,'Audience A','audA')}${compareOn?socialAudiencePanelHtml(b,'Audience B','audB'):''}</div></div></div>`;
    const pa=card.querySelector('.social-scale-panel.audA'); attachSocialScaleClicks(pa,a,cfg.scale,`${d.postNo} · Audience A`);
    if(compareOn){ const pb=card.querySelector('.social-scale-panel.audB'); attachSocialScaleClicks(pb,b,cfg.scale,`${d.postNo} · Audience B`); }
    wrap.appendChild(card);
  });
  vizArea.appendChild(wrap);
  document.getElementById('panelFootnote').textContent = compareOn
    ? 'Each pie shows the full five-level interest scale for the active audience definition. Top 2 Box and Bottom 2 Box are grouped below each pie. Click a response level or grouped box to profile that audience.'
    : 'Each pie shows the full five-level interest scale. Top 2 Box and Bottom 2 Box are grouped below the pie. Click a response level or grouped box to open its demographic profile below.';
}

function renderCategoricalModule(mod, rowsA, rowsB) {
  const vizArea = document.getElementById('vizArea');
  const labels = CAT_LABELS[mod.field] || {};
  const distA = catDist(rowsA, mod.field);
  const distB = compareOn ? catDist(rowsB, mod.field) : null;
  const hasSummary = !!mod.summaryCats;
  const wrap = hasSummary ? document.createElement('div') : null;
  const barsCol = hasSummary ? document.createElement('div') : null;
  if (hasSummary) { wrap.className='scalewrap'; barsCol.className='scalebars'; }
  const targetEl = hasSummary ? barsCol : vizArea;

  const cats = Object.keys(labels).filter(c => distA.dist[c]!==undefined || (distB && distB.dist[c]!==undefined));
  Object.keys(distA.dist).forEach(c => { if (!cats.includes(c)) cats.push(c); });
  const data = cats.map(c => ({ cat:c, label: labels[c]||c, a: distA.dist[c]||0, b: distB?(distB.dist[c]||0):null }));
  if (mod.order) data.sort((x,y) => mod.order.indexOf(x.cat) - mod.order.indexOf(y.cat));
  else if (mod.rank) data.sort((x,y) => (y.a||0) - (x.a||0));
  // Otherwise preserve the category order defined in CAT_LABELS / source coding.
  // Ordered/profile categorical distributions should not be re-ranked by percentage.
  const maxV = 100;
  data.forEach(d => {
    const row = document.createElement('div'); row.className='barrow';
    if (compareOn) {
      const cA = catCount(rowsA, mod.field, d.cat), cB = catCount(rowsB, mod.field, d.cat);
      const sig = twoPropSig(cA.count, cA.n, cB.count, cB.n);
      row.innerHTML = `<div class="barlabel">${d.label}</div>
        <div class="bartrack">
          <div class="barfillA" style="width:${(d.a/maxV*100).toFixed(1)}%"></div>
          <div class="barfillB" style="width:${(d.b/maxV*100).toFixed(1)}%"></div>
        </div>
        <div class="barval"><div class="cmpvals"><span class="vA">A ${d.a.toFixed(0)}%</span><span class="vB">B ${d.b.toFixed(0)}%</span></div>${sigSuffix(sig, d.a, d.b)}</div>`;
    } else {
      row.innerHTML = `<div class="barlabel">${d.label}</div>
        <div class="bartrack"><div class="barfillSingle" style="width:${(d.a/maxV*100).toFixed(1)}%"></div></div>
        <div class="barval">${d.a.toFixed(0)}%</div>`;
      makeClickable(row, eligibleRows(rowsA, mod.field), r => val(r, mod.field) === d.cat, d.label);
    }
    targetEl.appendChild(row);
  });

  if (hasSummary) {
    wrap.appendChild(barsCol);
    const cfg=mod.summaryCats;
    const sum=(dist,cats)=>cats.reduce((s,c)=>s+(dist.dist[c]||0),0);
    const topA=sum(distA,cfg.topCats), botA=sum(distA,cfg.bottomCats);
    const topB=distB?sum(distB,cfg.topCats):null, botB=distB?sum(distB,cfg.bottomCats):null;
    const sqCol=document.createElement('div'); sqCol.className='sqcol';
    const top=document.createElement('div'); top.className='sqtile pos';
    top.innerHTML=`<div class="sqval" style="color:var(--posB)">${topA.toFixed(0)}%</div>${compareOn?`<div class="sqvalB" style="color:var(--posB)">B: ${topB.toFixed(0)}%</div>`:''}<div class="sqlabel">${cfg.topLabel}</div>`;
    const bottom=document.createElement('div'); bottom.className='sqtile neg';
    bottom.innerHTML=`<div class="sqval" style="color:var(--negB)">${botA.toFixed(0)}%</div>${compareOn?`<div class="sqvalB" style="color:var(--negB)">B: ${botB.toFixed(0)}%</div>`:''}<div class="sqlabel">${cfg.bottomLabel}</div>`;
    if (!compareOn) {
      const universe=eligibleRows(rowsA,mod.field);
      makeClickable(top, universe, r=>cfg.topCats.includes(val(r,mod.field)), cfg.topLabel);
      makeClickable(bottom, universe, r=>cfg.bottomCats.includes(val(r,mod.field)), cfg.bottomLabel);
    } else {
      const universeA=eligibleRows(rowsA,mod.field), universeB=eligibleRows(rowsB,mod.field);
      makeMetricClickable(top.querySelector('.sqval'), universeA, r=>cfg.topCats.includes(val(r,mod.field)), `${cfg.topLabel} · Audience A`);
      makeMetricClickable(top.querySelector('.sqvalB'), universeB, r=>cfg.topCats.includes(val(r,mod.field)), `${cfg.topLabel} · Audience B`);
      makeMetricClickable(bottom.querySelector('.sqval'), universeA, r=>cfg.bottomCats.includes(val(r,mod.field)), `${cfg.bottomLabel} · Audience A`);
      makeMetricClickable(bottom.querySelector('.sqvalB'), universeB, r=>cfg.bottomCats.includes(val(r,mod.field)), `${cfg.bottomLabel} · Audience B`);
    }
    sqCol.appendChild(top); sqCol.appendChild(bottom); wrap.appendChild(sqCol); vizArea.appendChild(wrap);
  }

  document.getElementById('panelFootnote').textContent = `Base | Audience A: ${distA.n}` + (compareOn ? `  ·  Audience B: ${distB.n}` : '');
}


function renderVisitIntentModule(mod, rowsA, rowsB) {
  const vizArea = document.getElementById('vizArea');
  const labels = CAT_LABELS[mod.field] || {};
  const distA = catDist(rowsA, mod.field);
  const distB = compareOn ? catDist(rowsB, mod.field) : null;
  const order = ['soon','within_year','within_3y','later','someday','notsure','no'];
  const wrap=document.createElement('div'); wrap.className='scalewrap';
  const bars=document.createElement('div'); bars.className='scalebars';
  order.forEach(cat=>{
    if (distA.dist[cat]===undefined && (!distB || distB.dist[cat]===undefined)) return;
    const a=distA.dist[cat]||0, b=distB?(distB.dist[cat]||0):null;
    const row=document.createElement('div'); row.className='barrow';
    if(compareOn){
      const cA=catCount(rowsA,mod.field,cat), cB=catCount(rowsB,mod.field,cat);
      const sig=twoPropSig(cA.count,cA.n,cB.count,cB.n);
      row.innerHTML=`<div class="barlabel">${labels[cat]||cat}</div><div class="bartrack"><div class="barfillA" style="width:${a.toFixed(1)}%"></div><div class="barfillB" style="width:${b.toFixed(1)}%"></div></div><div class="barval"><div class="cmpvals"><span class="vA">A ${a.toFixed(0)}%</span><span class="vB">B ${b.toFixed(0)}%</span></div>${sigSuffix(sig,a,b)}</div>`;
    } else {
      row.innerHTML=`<div class="barlabel">${labels[cat]||cat}</div><div class="bartrack"><div class="barfillSingle" style="width:${a.toFixed(1)}%"></div></div><div class="barval">${a.toFixed(0)}%</div>`;
      makeClickable(row, eligibleRows(rowsA,mod.field), r=>val(r,mod.field)===cat, labels[cat]||cat);
    }
    bars.appendChild(row);
  });
  wrap.appendChild(bars);
  const groups=[
    {cats:['soon','within_year','within_3y'], label:'Near-term visit intent (within 3 years)', cls:'pos', color:'var(--posB)'},
    {cats:['later','someday'], label:'Later visit intention', cls:'neu', color:'var(--navy)'},
    {cats:['notsure','no'], label:'No current plan / not sure', cls:'neg', color:'var(--negB)'}
  ];
  const sq=document.createElement('div'); sq.className='sqcol';
  const sum=(d,cats)=>cats.reduce((x,c)=>x+(d.dist[c]||0),0);
  groups.forEach(g=>{
    const a=sum(distA,g.cats), b=distB?sum(distB,g.cats):null;
    const tile=document.createElement('div'); tile.className=`sqtile ${g.cls}`;
    tile.innerHTML=`<div class="sqval" style="color:${g.color}">${a.toFixed(0)}%</div>${compareOn?`<div class="sqvalB" style="color:${g.color}">B: ${b.toFixed(0)}%</div>`:''}<div class="sqlabel">${g.label}</div>`;
    if(!compareOn){
      const u=eligibleRows(rowsA,mod.field); makeClickable(tile,u,r=>g.cats.includes(val(r,mod.field)),g.label);
    } else {
      const uA=eligibleRows(rowsA,mod.field), uB=eligibleRows(rowsB,mod.field);
      makeMetricClickable(tile.querySelector('.sqval'),uA,r=>g.cats.includes(val(r,mod.field)),`${g.label} · Audience A`);
      makeMetricClickable(tile.querySelector('.sqvalB'),uB,r=>g.cats.includes(val(r,mod.field)),`${g.label} · Audience B`);
    }
    sq.appendChild(tile);
  });
  wrap.appendChild(sq); vizArea.appendChild(wrap);
  document.getElementById('panelFootnote').textContent=`Base | Audience A: ${distA.n}`+(compareOn?`  ·  Audience B: ${distB.n}`:'');
}

const SENTIMENT_GROUPS = [
  { key:'pos', label:'Positive', cats:['pos_mostly','pos_more'] },
  { key:'neu', label:'Neutral (positive and negative equally)', cats:['neutral'] },
  { key:'neg', label:'Negative', cats:['neg_more','neg_mostly'] },
];

function groupCount(rows, field, cats) {
  let n=0, count=0;
  rows.forEach(r => { const v = val(r,field); if (v!==null && v!==undefined) { n++; if (cats.includes(v)) count++; } });
  return { n, count };
}

function renderSentimentModule(mod, rowsA, rowsB) {
  const vizArea = document.getElementById('vizArea');
  const distA = catDist(rowsA, mod.field);
  const distB = compareOn ? catDist(rowsB, mod.field) : null;

  function grouped(dist) {
    const g = {};
    SENTIMENT_GROUPS.forEach(grp => { g[grp.key] = grp.cats.reduce((s,c) => s + (dist.dist[c]||0), 0); });
    return g;
  }
  const gA = grouped(distA);
  const gB = distB ? grouped(distB) : null;
  const maxV = 100; // fixed 0-100% basis, not relative to the largest value in view

  // Net score summary card FIRST, above the bars
  const nssA = Math.round((gA.pos - gA.neg) * 10) / 10;
  const nssB = gB ? Math.round((gB.pos - gB.neg) * 10) / 10 : null;
  const nssWrap = document.createElement('div');
  nssWrap.className = 'kpi-grid';
  nssWrap.style.marginBottom = '16px';
  nssWrap.innerHTML = `
    <div class="kpi">
      <div class="kval" style="color:${nssA>=0?'var(--posB)':'var(--negB)'};">${nssA>=0?'+':''}${nssA.toFixed(0)}</div>
      <div class="klabel">Net sentiment score${compareOn?', Audience A':''} (% positive minus % negative)</div>
    </div>
    ${compareOn ? `<div class="kpi">
      <div class="kval" style="color:${nssB>=0?'var(--posB)':'var(--negB)'};">${nssB>=0?'+':''}${nssB.toFixed(0)}</div>
      <div class="klabel">Net sentiment score, Audience B (% positive minus % negative)</div>
    </div>` : ''}
  `;
  vizArea.appendChild(nssWrap);

  const colorFor = { pos: ['var(--posA)','var(--posB)'], neu: ['var(--neuA)','var(--neuB)'], neg: ['var(--negA)','var(--negB)'] };
  SENTIMENT_GROUPS.forEach(grp => {
    const row = document.createElement('div'); row.className='barrow';
    const a = gA[grp.key], b = gB ? gB[grp.key] : null;
    const [cA, cB] = colorFor[grp.key];
    if (compareOn) {
      const gcA = groupCount(rowsA, mod.field, grp.cats), gcB = groupCount(rowsB, mod.field, grp.cats);
      const sig = twoPropSig(gcA.count, gcA.n, gcB.count, gcB.n);
      row.innerHTML = `<div class="barlabel">${grp.label}</div>
        <div class="bartrack">
          <div class="barfillA" style="width:${(a/maxV*100).toFixed(1)}%"></div>
          <div class="barfillB" style="width:${(b/maxV*100).toFixed(1)}%"></div>
        </div>
        <div class="barval"><div class="cmpvals"><span class="vA">A ${a.toFixed(0)}%</span><span class="vB">B ${b.toFixed(0)}%</span></div>${sigSuffix(sig, a, b)}</div>`;
    } else {
      row.innerHTML = `<div class="barlabel">${grp.label}</div>
        <div class="bartrack"><div style="background:${cA};height:100%;border-radius:4px;width:${(a/maxV*100).toFixed(1)}%"></div></div>
        <div class="barval">${a.toFixed(0)}%</div>`;
      makeClickable(row, eligibleRows(rowsA, mod.field), r => grp.cats.includes(val(r, mod.field)), grp.label);
    }
    vizArea.appendChild(row);
  });

  document.getElementById('panelFootnote').textContent = `Base | Audience A: ${distA.n}` + (compareOn ? `  ·  Audience B: ${distB.n}` : '') + `. Positive combines "mostly positive" and "more positive than negative"; negative combines "more negative than positive" and "mostly negative".`;
}

