function renderScaleBarModule(mod, rowsA, rowsB) {
  const vizArea = document.getElementById('vizArea');
  const meta = SCALEBAR_META[mod.field];
  const distA = catDist(rowsA, mod.field);
  const distB = compareOn ? catDist(rowsB, mod.field) : null;

  const n = meta.order.length;
  // 5-step diverging color per position (index 0..n-1), blue -> gray -> red
  const stopsA = ['var(--posB)','var(--posA)','var(--neuA)','var(--negA)','var(--negB)'];
  const stopsB = ['var(--posB)','var(--posA)','var(--neuB)','var(--negA)','var(--negB)'];

  const wrap = document.createElement('div');
  wrap.className = 'scalewrap';

  const barsCol = document.createElement('div');
  barsCol.className = 'scalebars';
  const maxV = 100; // fixed 0-100% basis, not relative to the largest value in view
  meta.order.forEach((k,i) => {
    const a = distA.dist[k]||0, b = distB ? (distB.dist[k]||0) : null;
    const row = document.createElement('div'); row.className='barrow';
    if (compareOn) {
      const cA = catCount(rowsA, mod.field, k), cB = catCount(rowsB, mod.field, k);
      const sig = twoPropSig(cA.count, cA.n, cB.count, cB.n);
      row.innerHTML = `<div class="barlabel">${meta.labels[k]}</div>
        <div class="bartrack">
          <div class="barfillA" style="width:${(a/maxV*100).toFixed(1)}%"></div>
          <div class="barfillB" style="width:${(b/maxV*100).toFixed(1)}%"></div>
        </div>
        <div class="barval"><div class="cmpvals"><span class="vA">A ${a.toFixed(0)}%</span><span class="vB">B ${b.toFixed(0)}%</span></div>${sigSuffix(sig, a, b)}</div>`;
    } else {
      row.innerHTML = `<div class="barlabel">${meta.labels[k]}</div>
        <div class="bartrack"><div style="background:${stopsA[i]};height:100%;border-radius:4px;width:${(a/maxV*100).toFixed(1)}%"></div></div>
        <div class="barval">${a.toFixed(0)}%</div>`;
      makeClickable(row, eligibleRows(rowsA, mod.field), r => val(r, mod.field) === k, meta.labels[k]);
    }
    barsCol.appendChild(row);
  });
  wrap.appendChild(barsCol);

  function sumCats(dist, cats) { return cats.reduce((s,c) => s + (dist.dist[c]||0), 0); }
  const topA = sumCats(distA, meta.top2), botA = sumCats(distA, meta.bottom2), netA = Math.round((topA-botA)*10)/10;
  const topB = distB ? sumCats(distB, meta.top2) : null;
  const botB = distB ? sumCats(distB, meta.bottom2) : null;
  const netB = distB!==null && topB!==null ? Math.round((topB-botB)*10)/10 : null;

  const sqCol = document.createElement('div');
  sqCol.className = 'sqcol';

  const posTile = document.createElement('div');
  posTile.className = 'sqtile pos';
  posTile.innerHTML = `<div class="sqval" style="color:var(--posB)">${topA.toFixed(0)}%</div>
    ${compareOn ? `<div class="sqvalB" style="color:var(--posB)">B: ${topB.toFixed(0)}%</div>` : ''}
    <div class="sqlabel">${meta.topLabel}</div>`;
  sqCol.appendChild(posTile);

  let netTile = null;
  if (meta.showNet !== false) {
    netTile = document.createElement('div');
    netTile.className = 'sqtile net';
    netTile.innerHTML = `<div class="sqval" style="color:${netA>=0?'var(--posB)':'var(--negB)'}">${netA>=0?'+':''}${netA.toFixed(0)}</div>
      ${compareOn ? `<div class="sqvalB" style="color:${netB>=0?'var(--posB)':'var(--negB)'}">B: ${netB>=0?'+':''}${netB.toFixed(0)}</div>` : ''}
      <div class="sqlabel">${meta.netLabel}</div>`;
    sqCol.appendChild(netTile);
  }

  const negTile = document.createElement('div');
  negTile.className = 'sqtile neg';
  negTile.innerHTML = `<div class="sqval" style="color:var(--negB)">${botA.toFixed(0)}%</div>
    ${compareOn ? `<div class="sqvalB" style="color:var(--negB)">B: ${botB.toFixed(0)}%</div>` : ''}
    <div class="sqlabel">${meta.bottomLabel}</div>`;
  sqCol.appendChild(negTile);

  wrap.appendChild(sqCol);

  if (!compareOn) {
    const universe=eligibleRows(rowsA,mod.field);
    makeClickable(posTile, universe, r => meta.top2.includes(val(r, mod.field)), meta.topLabel);
    makeClickable(negTile, universe, r => meta.bottom2.includes(val(r, mod.field)), meta.bottomLabel);
    if (netTile) makeClickable(netTile, universe, r => { const v = val(r, mod.field); return v!==null && v!==undefined; }, `${mod.label} (base)`);
  } else {
    const universeA=eligibleRows(rowsA,mod.field), universeB=eligibleRows(rowsB,mod.field);
    makeMetricClickable(posTile.querySelector('.sqval'), universeA, r=>meta.top2.includes(val(r,mod.field)), `${meta.topLabel} · Audience A`);
    makeMetricClickable(posTile.querySelector('.sqvalB'), universeB, r=>meta.top2.includes(val(r,mod.field)), `${meta.topLabel} · Audience B`);
    makeMetricClickable(negTile.querySelector('.sqval'), universeA, r=>meta.bottom2.includes(val(r,mod.field)), `${meta.bottomLabel} · Audience A`);
    makeMetricClickable(negTile.querySelector('.sqvalB'), universeB, r=>meta.bottom2.includes(val(r,mod.field)), `${meta.bottomLabel} · Audience B`);
  }

  vizArea.appendChild(wrap);
  document.getElementById('panelFootnote').textContent = `Base | Audience A: ${distA.n}` + (compareOn ? `  ·  Audience B: ${distB.n}` : '');
}

const RECALL_ORDER = ['yes_all','several','once','dontremember','no'];
const RECALL_LABELS = { yes_all:'Yes (all, once or more)', several:'Yes, several times', once:'Yes, once or twice', dontremember:'I don\u2019t remember', no:'No' };
const RECALL_COLORS_A = { yes_all:'var(--posB)', several:'var(--posB)', once:'var(--posA)', dontremember:'var(--neuA)', no:'var(--negA)' };
const RECALL_COLORS_B = { yes_all:'var(--posB)', several:'var(--posB)', once:'var(--posA)', dontremember:'var(--neuB)', no:'var(--negB)' };
const RECALL_GROUPS = { yes_all: ['once','several'] };

function numericBandCount(rows, field, testFn) {
  let n=0, count=0;
  rows.forEach(r => { const v = val(r,field); if (v!==null && v!==undefined) { n++; if (testFn(v)) count++; } });
  return { n, count };
}

function npsStats(rows, field) {
  const vals = rows.map(r => val(r,field)).filter(v => v!==null && v!==undefined);
  const n = vals.length;
  if (n===0) return { n:0, avg:null, promoters:null, passives:null, detractors:null, nps:null };
  const avg = vals.reduce((s,v)=>s+v,0)/n;
  const promoters = vals.filter(v=>v>=9).length/n*100;
  const passives = vals.filter(v=>v>=7 && v<=8).length/n*100;
  const detractors = vals.filter(v=>v<=6).length/n*100;
  return { n, avg: Math.round(avg*10)/10, promoters: Math.round(promoters*10)/10, passives: Math.round(passives*10)/10, detractors: Math.round(detractors*10)/10, nps: Math.round((promoters-detractors)*10)/10 };
}

const SEGMENT_DEFS = [
  { key:'enthusiasts', label:'Vietnam Enthusiasts', color:'pos',
    desc:'Open to foreign media AND highly interested in Vietnam specifically. The core, most convertible audience.',
    test: r => val(r,'e5_seeks_foreign_media')===1 && val(r,'a1_vietnam')===1 },
  { key:'explorers', label:'Global Explorers', color:'neu',
    desc:'Open to foreign media generally, but not yet tuned into Vietnam specifically. A growth opportunity through better targeting or discovery.',
    test: r => val(r,'e5_seeks_foreign_media')===1 && val(r,'a1_vietnam')===0 },
  { key:'loyalists', label:'Vietnam Focused', color:'neu',
    desc:'Specifically interested in Vietnam, often via personal connection, but not broadly curious about foreign media in general.',
    test: r => val(r,'e5_seeks_foreign_media')===0 && val(r,'a1_vietnam')===1 },
  { key:'disengaged', label:'Disengaged', color:'neg',
    desc:'Neither broadly open to foreign content nor specifically interested in Vietnam. Lowest near-term priority.',
    test: r => val(r,'e5_seeks_foreign_media')===0 && val(r,'a1_vietnam')===0 },
];

function renderSegmentModule(mod, rowsA, rowsB) {
  const vizArea = document.getElementById('vizArea');

  const grid = document.createElement('div');
  grid.className = 'seggrid';
  const totalA = rowsA.length;
  const totalB = compareOn ? rowsB.length : 0;
  SEGMENT_DEFS.forEach(seg => {
    const subRowsA = rowsA.filter(seg.test);
    const pctA = totalA>0 ? (subRowsA.length/totalA*100) : 0;
    const tile = document.createElement('div');
    tile.className = 'segtile';
    const color = seg.color==='pos' ? 'var(--posB)' : seg.color==='neg' ? 'var(--negB)' : 'var(--text-muted)';

    if (compareOn) {
      const subRowsB = rowsB.filter(seg.test);
      const pctB = totalB>0 ? (subRowsB.length/totalB*100) : 0;
      const segSig = twoPropSig(subRowsA.length, totalA, subRowsB.length, totalB);
      tile.innerHTML = `<div class="segname">${seg.label}</div>
        <div class="segdesc">${seg.desc}</div>
        <div class="segcompare">
          <div class="segcompareval segA"><div class="segab">Audience A</div><div class="segpctA">${pctA.toFixed(0)}%</div><div class="segn">n=${subRowsA.length.toLocaleString()} / ${totalA.toLocaleString()}</div></div>
          <div class="segcompareval segB"><div class="segab">Audience B</div><div class="segpctB">${pctB.toFixed(0)}%</div><div class="segn">n=${subRowsB.length.toLocaleString()} / ${totalB.toLocaleString()}</div></div>
        </div>
        <div style="margin-top:8px">${sigSuffix(segSig, pctA, pctB)}</div>`;
      const aBox = tile.querySelector('.segA');
      const bBox = tile.querySelector('.segB');
      makeClickable(aBox, rowsA, seg.test, `${seg.label} - Audience A`);
      makeClickable(bBox, rowsB, seg.test, `${seg.label} - Audience B`);
    } else {
      tile.innerHTML = `<div class="segpct" style="color:${color}">${pctA.toFixed(0)}%</div>
        <div class="segname">${seg.label}</div>
        <div class="segdesc">${seg.desc}</div>`;
      makeClickable(tile, rowsA, seg.test, seg.label);
    }
    grid.appendChild(tile);
  });
  vizArea.appendChild(grid);

  document.getElementById('panelFootnote').textContent = compareOn
    ? `Base | Audience A: ${totalA.toLocaleString()} · Audience B: ${totalB.toLocaleString()}. Click an audience value within a segment to see its demographic profile below.`
    : `Base: ${totalA.toLocaleString()}. Click any segment to see its demographic profile below.`;
}

function renderNPSModule(mod, rowsA, rowsB) {
  const vizArea = document.getElementById('vizArea');
  const sA = npsStats(rowsA, mod.field);
  const sB = compareOn ? npsStats(rowsB, mod.field) : null;

  const summary = document.createElement('div');
  summary.className = 'kpi-grid';
  summary.style.marginBottom = '16px';
  summary.innerHTML = `
    <div class="kpi">
      <div class="kval">${sA.avg!==null?sA.avg.toFixed(1):'n/a'}</div>
      <div class="klabel">Average score, 0 to 10${compareOn?', Audience A':''}</div>
      ${compareOn ? `<div class="kvalB">B: ${sB.avg!==null?sB.avg.toFixed(1):'n/a'}</div>` : ''}
    </div>
    <div class="kpi">
      <div class="kval" style="color:${sA.nps!==null && sA.nps>=0?'var(--posB)':'var(--negB)'};">${sA.nps!==null?(sA.nps>=0?'+':'')+sA.nps.toFixed(0):'n/a'}</div>
      <div class="klabel">Net recommendation score (promoters minus detractors)</div>
      ${compareOn ? `<div class="kvalB">B: ${sB.nps!==null?(sB.nps>=0?'+':'')+sB.nps.toFixed(0):'n/a'}</div>` : ''}
    </div>
  `;
  vizArea.appendChild(summary);

  const bands = [
    { label:'Promoters (9\u201310)', a:sA.promoters, b:sB?sB.promoters:null, color:'var(--posB)', test:v=>v>=9 },
    { label:'Passives (7\u20138)', a:sA.passives, b:sB?sB.passives:null, color:'var(--neuA)', test:v=>v>=7&&v<=8 },
    { label:'Detractors (0\u20136)', a:sA.detractors, b:sB?sB.detractors:null, color:'var(--negB)', test:v=>v<=6 },
  ];
  bands.forEach(band => {
    const row = document.createElement('div'); row.className='barrow';
    if (compareOn) {
      const cA = numericBandCount(rowsA, mod.field, band.test), cB = numericBandCount(rowsB, mod.field, band.test);
      const sig = twoPropSig(cA.count, cA.n, cB.count, cB.n);
      row.innerHTML = `<div class="barlabel">${band.label}</div>
        <div class="bartrack">
          <div class="barfillA" style="width:${(band.a||0)}%"></div>
          <div class="barfillB" style="width:${(band.b||0)}%"></div>
        </div>
        <div class="barval"><div class="cmpvals"><span class="vA">A ${band.a!==null?band.a.toFixed(0)+'%':'n/a'}</span><span class="vB">B ${band.b!==null?band.b.toFixed(0)+'%':'n/a'}</span></div>${sigSuffix(sig, band.a, band.b)}</div>`;
    } else {
      row.innerHTML = `<div class="barlabel">${band.label}</div>
        <div class="bartrack"><div style="background:${band.color};height:100%;border-radius:4px;width:${(band.a||0)}%"></div></div>
        <div class="barval">${band.a!==null?band.a.toFixed(0)+'%':'n/a'}</div>`;
      makeClickable(row, eligibleRows(rowsA, mod.field), r => { const v = val(r, mod.field); return v!==null && v!==undefined && band.test(v); }, band.label);
    }
    vizArea.appendChild(row);
  });

  document.getElementById('panelFootnote').textContent = `Base | Audience A: ${sA.n}` + (compareOn ? `  ·  Audience B: ${sB.n}` : '') + `. Asked only of people who watch Vietnam Today.`;
}

function renderRecallModule(mod, rowsA, rowsB) {
  const vizArea = document.getElementById('vizArea');
  const distA = catDist(rowsA, mod.field);
  const distB = compareOn ? catDist(rowsB, mod.field) : null;

  const topA = (distA.dist.once||0) + (distA.dist.several||0);
  const botA = (distA.dist.dontremember||0) + (distA.dist.no||0);
  const netA = Math.round((topA - botA) * 10) / 10;
  const topB = distB ? (distB.dist.once||0) + (distB.dist.several||0) : null;
  const botB = distB ? (distB.dist.dontremember||0) + (distB.dist.no||0) : null;
  const netB = distB ? Math.round((topB - botB) * 10) / 10 : null;

  const wrap = document.createElement('div');
  wrap.className = 'scalewrap';
  const barsCol = document.createElement('div');
  barsCol.className = 'scalebars';

  const displayOrder = ['several','once','dontremember','no'];
  const maxV = 100;
  displayOrder.forEach(k => {
    const a = distA.dist[k]||0;
    const b = distB ? (distB.dist[k]||0) : null;
    const row = document.createElement('div'); row.className='barrow';
    if (compareOn) {
      const cA = catCount(rowsA, mod.field, k);
      const cB = catCount(rowsB, mod.field, k);
      const sig = twoPropSig(cA.count, cA.n, cB.count, cB.n);
      row.innerHTML = `<div class="barlabel">${RECALL_LABELS[k]}</div>
        <div class="bartrack">
          <div class="barfillA" style="width:${(a/maxV*100).toFixed(1)}%"></div>
          <div class="barfillB" style="width:${(b/maxV*100).toFixed(1)}%"></div>
        </div>
        <div class="barval"><div class="cmpvals"><span class="vA">A ${a.toFixed(0)}%</span><span class="vB">B ${b.toFixed(0)}%</span></div>${sigSuffix(sig, a, b)}</div>`;
    } else {
      row.innerHTML = `<div class="barlabel">${RECALL_LABELS[k]}</div>
        <div class="bartrack"><div style="background:${RECALL_COLORS_A[k]};height:100%;border-radius:4px;width:${(a/maxV*100).toFixed(1)}%"></div></div>
        <div class="barval">${a.toFixed(0)}%</div>`;
      makeClickable(row, eligibleRows(rowsA, mod.field), r => val(r, mod.field) === k, RECALL_LABELS[k]);
    }
    barsCol.appendChild(row);
  });
  wrap.appendChild(barsCol);

  const sq = document.createElement('div'); sq.className='sqcol';
  const pos = document.createElement('div'); pos.className='sqtile pos';
  pos.innerHTML=`<div class="sqval" style="color:var(--posB)">${topA.toFixed(0)}%</div>${compareOn?`<div class="sqvalB" style="color:var(--posB)">B: ${topB.toFixed(0)}%</div>`:''}<div class="sqlabel">Recalled Vietnam news (top 2 box)</div>`;
  const neg = document.createElement('div'); neg.className='sqtile neg';
  neg.innerHTML=`<div class="sqval" style="color:var(--negB)">${botA.toFixed(0)}%</div>${compareOn?`<div class="sqvalB" style="color:var(--negB)">B: ${botB.toFixed(0)}%</div>`:''}<div class="sqlabel">Not recalled / don’t remember (bottom 2 box)</div>`;
  sq.append(pos,neg); wrap.appendChild(sq); vizArea.appendChild(wrap);

  if (!compareOn) {
    const u = eligibleRows(rowsA, mod.field);
    makeClickable(pos, u, r => ['once','several'].includes(val(r,mod.field)), 'Recalled Vietnam news (top 2 box)');
    makeClickable(neg, u, r => ['dontremember','no'].includes(val(r,mod.field)), 'Not recalled / don’t remember (bottom 2 box)');
  } else {
    const uA=eligibleRows(rowsA,mod.field), uB=eligibleRows(rowsB,mod.field);
    makeMetricClickable(pos.querySelector('.sqval'),uA,r=>['once','several'].includes(val(r,mod.field)),'Recalled Vietnam news · Audience A');
    makeMetricClickable(pos.querySelector('.sqvalB'),uB,r=>['once','several'].includes(val(r,mod.field)),'Recalled Vietnam news · Audience B');
    makeMetricClickable(neg.querySelector('.sqval'),uA,r=>['dontremember','no'].includes(val(r,mod.field)),'Not recalled / don’t remember · Audience A');
    makeMetricClickable(neg.querySelector('.sqvalB'),uB,r=>['dontremember','no'].includes(val(r,mod.field)),'Not recalled / don’t remember · Audience B');
  }

  document.getElementById('panelFootnote').textContent = `Base | Audience A: ${distA.n}` + (compareOn ? `  ·  Audience B: ${distB.n}` : '') + `. Top 2 Box combines “yes, once or twice” and “yes, several times”; Bottom 2 Box combines “I don’t remember” and “No”.`;
}

const SCALE5_ORDER = ['vi','i','si','sli','na'];
const SCALE5_LABELS = { vi:'Very interested', i:'Interested', si:'Somewhat interested', sli:'Slightly interested', na:'Not at all interested' };
const SCALE5_COLORS = { vi:'var(--posB)', i:'var(--posA)', si:'var(--neuA)', sli:'#E0A08F', na:'var(--negB)' };

function renderFullScaleModule(mod, rowsA, rowsB) {
  const vizArea = document.getElementById('vizArea');

  const legend = document.createElement('div');
  legend.className = 'scalelegend';
  legend.innerHTML = SCALE5_ORDER.map(k => `<span><i style="background:${SCALE5_COLORS[k]}"></i>${SCALE5_LABELS[k]}</span>`).join('');
  vizArea.appendChild(legend);

  function distFor(rows, field) {
    const d = catDist(rows, field);
    const out = {};
    SCALE5_ORDER.forEach(k => { out[k] = d.dist[k] || 0; });
    out._n = d.n;
    return out;
  }

  function stackTrack(dist, extraClass, clickCtx) {
    const track = document.createElement('div');
    track.className = 'stacktrack' + (extraClass ? ' '+extraClass : '');
    SCALE5_ORDER.forEach(k => {
      const seg = document.createElement('div');
      seg.className = 'stackseg';
      const w = dist[k];
      seg.style.width = w.toFixed(1) + '%';
      seg.style.background = SCALE5_COLORS[k];
      if (w >= 7) seg.textContent = w.toFixed(0) + '%';
      if (clickCtx) {
        seg.style.cursor = 'pointer';
        seg.onclick = () => {
          const subRows = clickCtx.universeRows.filter(r => val(r, clickCtx.field) === k);
          showDrilldown(subRows, clickCtx.universeRows, `${clickCtx.itemLabel}: ${SCALE5_LABELS[k]}`);
        };
      }
      track.appendChild(seg);
    });
    return track;
  }

  // sort items by net (vi+i) of Audience A, descending
  const items = mod.fields.map(([field,label]) => {
    const dA = distFor(rowsA, field);
    return { field, label, dA };
  });
  items.sort((x,y) => (y.dA.vi+y.dA.i) - (x.dA.vi+x.dA.i));

  items.forEach(({field,label,dA}) => {
    const wrap = document.createElement('div');
    wrap.className = 'stackrow';
    const t2bA = (dA.vi+dA.i).toFixed(0), b2bA = (dA.sli+dA.na).toFixed(0);
    if (compareOn) {
      const dB = distFor(rowsB, field);
      const t2bB = (dB.vi+dB.i).toFixed(0), b2bB = (dB.sli+dB.na).toFixed(0);
      const head = document.createElement('div');
      head.className = 'stacklabel';
      head.innerHTML = `<span>${label}</span><span class="scale-summary"><span class="scale-pair A"><span class="aud">A</span><span class="metric">T2B <strong>${t2bA}%</strong></span><span class="metric">B2B <strong>${b2bA}%</strong></span></span><span class="scale-pair B"><span class="aud">B</span><span class="metric">T2B <strong>${t2bB}%</strong></span><span class="metric">B2B <strong>${b2bB}%</strong></span></span></span>`;
      wrap.appendChild(head);
      wrap.appendChild(stackTrack(dA));
      wrap.appendChild(stackTrack(dB, 'compareb'));
    } else {
      const head = document.createElement('div');
      head.className = 'stacklabel';
      head.innerHTML = `<span>${label}</span><span class="scale-summary"><span class="scale-pair A"><span class="metric">T2B <strong>${t2bA}%</strong></span><span class="metric">B2B <strong>${b2bA}%</strong></span></span></span>`;
      wrap.appendChild(head);
      wrap.appendChild(stackTrack(dA, null, { field, universeRows: eligibleRows(rowsA, field), itemLabel: label }));
    }
    vizArea.appendChild(wrap);
  });

  document.getElementById('panelFootnote').textContent = compareOn
    ? `Top bar = Audience A, bottom bar = Audience B, for each item. Base | Audience A: ${rowsA.length}  ·  Audience B: ${rowsB.length}.`
    : `Base: ${rowsA.length}.`;
}



function renderCoverageBarModule(mod, rowsA, rowsB) {
  const vizArea = document.getElementById('vizArea');
  const order = ['strongly_agree','somewhat_agree','neutral','somewhat_disagree','strongly_disagree','not_familiar'];
  const labels = {
    strongly_agree:'Strongly agree', somewhat_agree:'Somewhat agree', neutral:'Neither agree nor disagree',
    somewhat_disagree:'Somewhat disagree', strongly_disagree:'Strongly disagree', not_familiar:'Not familiar enough to say'
  };
  const colors = ['var(--posB)','var(--posA)','var(--neuA)','#E0A08F','var(--negB)','#B9C2CC'];
  const distA = catDist(rowsA, mod.field);
  const distB = compareOn ? catDist(rowsB, mod.field) : null;
  const wrap = document.createElement('div'); wrap.className='scalewrap';
  const barsCol = document.createElement('div'); barsCol.className='scalebars';
  order.forEach((k,i)=>{
    const a=distA.dist[k]||0, b=distB ? (distB.dist[k]||0) : null;
    const row=document.createElement('div'); row.className='barrow';
    if(compareOn){
      const cA=catCount(rowsA,mod.field,k), cB=catCount(rowsB,mod.field,k);
      const sig=twoPropSig(cA.count,cA.n,cB.count,cB.n);
      row.innerHTML=`<div class="barlabel">${labels[k]}</div>
        <div class="bartrack"><div class="barfillA" style="width:${a.toFixed(1)}%"></div><div class="barfillB" style="width:${b.toFixed(1)}%"></div></div>
        <div class="barval"><div class="cmpvals"><span class="vA">A ${a.toFixed(0)}%</span><span class="vB">B ${b.toFixed(0)}%</span></div>${sigSuffix(sig,a,b)}</div>`;
    } else {
      row.innerHTML=`<div class="barlabel">${labels[k]}</div><div class="bartrack"><div style="background:${colors[i]};height:100%;border-radius:4px;width:${a.toFixed(1)}%"></div></div><div class="barval">${a.toFixed(0)}%</div>`;
      makeClickable(row, eligibleRows(rowsA,mod.field), r=>val(r,mod.field)===k, labels[k]);
    }
    barsCol.appendChild(row);
  });
  wrap.appendChild(barsCol);
  const sum=(dist,cats)=>cats.reduce((t,c)=>t+(dist.dist[c]||0),0);
  const topA=sum(distA,['strongly_agree','somewhat_agree']);
  const botA=sum(distA,['somewhat_disagree','strongly_disagree']);
  const netA=Math.round((topA-botA)*10)/10;
  const topB=distB?sum(distB,['strongly_agree','somewhat_agree']):null;
  const botB=distB?sum(distB,['somewhat_disagree','strongly_disagree']):null;
  const netB=distB?Math.round((topB-botB)*10)/10:null;
  const sq=document.createElement('div'); sq.className='sqcol';
  const pos=document.createElement('div'); pos.className='sqtile pos';
  pos.innerHTML=`<div class="sqval" style="color:var(--posB)">${topA.toFixed(0)}%</div>${compareOn?`<div class="sqvalB" style="color:var(--posB)">B: ${topB.toFixed(0)}%</div>`:''}<div class="sqlabel">Positive coverage (top 2 box)</div>`;
  const net=document.createElement('div'); net.className='sqtile net';
  net.innerHTML=`<div class="sqval" style="color:${netA>=0?'var(--posB)':'var(--negB)'}">${netA>=0?'+':''}${netA.toFixed(0)}</div>${compareOn?`<div class="sqvalB" style="color:${netB>=0?'var(--posB)':'var(--negB)'}">B: ${netB>=0?'+':''}${netB.toFixed(0)}</div>`:''}<div class="sqlabel">Net positive coverage</div>`;
  const neg=document.createElement('div'); neg.className='sqtile neg';
  neg.innerHTML=`<div class="sqval" style="color:var(--negB)">${botA.toFixed(0)}%</div>${compareOn?`<div class="sqvalB" style="color:var(--negB)">B: ${botB.toFixed(0)}%</div>`:''}<div class="sqlabel">Negative coverage (bottom 2 box)</div>`;
  sq.append(pos,net,neg); wrap.appendChild(sq); vizArea.appendChild(wrap);
  if(!compareOn){
    const u=eligibleRows(rowsA,mod.field);
    makeClickable(pos,u,r=>['strongly_agree','somewhat_agree'].includes(val(r,mod.field)),'Positive coverage (top 2 box)');
    makeClickable(neg,u,r=>['somewhat_disagree','strongly_disagree'].includes(val(r,mod.field)),'Negative coverage (bottom 2 box)');
  } else {
    const uA=eligibleRows(rowsA,mod.field),uB=eligibleRows(rowsB,mod.field);
    makeMetricClickable(pos.querySelector('.sqval'),uA,r=>['strongly_agree','somewhat_agree'].includes(val(r,mod.field)),'Positive coverage · Audience A');
    makeMetricClickable(pos.querySelector('.sqvalB'),uB,r=>['strongly_agree','somewhat_agree'].includes(val(r,mod.field)),'Positive coverage · Audience B');
    makeMetricClickable(neg.querySelector('.sqval'),uA,r=>['somewhat_disagree','strongly_disagree'].includes(val(r,mod.field)),'Negative coverage · Audience A');
    makeMetricClickable(neg.querySelector('.sqvalB'),uB,r=>['somewhat_disagree','strongly_disagree'].includes(val(r,mod.field)),'Negative coverage · Audience B');
  }
  document.getElementById('panelFootnote').textContent=`Base | Audience A: ${distA.n}`+(compareOn?`  ·  Audience B: ${distB.n}`:'')+'. “Not familiar enough to say” remains in the question base.';
}

const AGREE6_ORDER = ['strongly_agree','somewhat_agree','neutral','somewhat_disagree','strongly_disagree','not_familiar'];
const AGREE6_LABELS = {
  strongly_agree:'Strongly agree', somewhat_agree:'Somewhat agree', neutral:'Neither agree nor disagree',
  somewhat_disagree:'Somewhat disagree', strongly_disagree:'Strongly disagree', not_familiar:'Not familiar enough to say'
};
const AGREE6_COLORS = {
  strongly_agree:'var(--posB)', somewhat_agree:'var(--posA)', neutral:'var(--neuA)',
  somewhat_disagree:'#E0A08F', strongly_disagree:'var(--negB)', not_familiar:'#B9C2CC'
};

function renderAgreementScaleModule(mod, rowsA, rowsB) {
  const vizArea = document.getElementById('vizArea');
  const legend = document.createElement('div');
  legend.className = 'scalelegend';
  legend.innerHTML = AGREE6_ORDER.map(k => `<span><i style="background:${AGREE6_COLORS[k]}"></i>${AGREE6_LABELS[k]}</span>`).join('');
  vizArea.appendChild(legend);

  const note = document.createElement('div');
  note.className = 'agreement-note';
  note.textContent = 'Top 2 Box = strongly + somewhat agree. Bottom 2 Box = strongly + somewhat disagree. Net agreement = Top 2 Box minus Bottom 2 Box.';
  vizArea.appendChild(note);

  function distFor(rows, field) {
    const d=catDist(rows,field), out={};
    AGREE6_ORDER.forEach(k => { out[k]=d.dist[k]||0; });
    out._n=d.n; return out;
  }
  function summary(dist) {
    const top=(dist.strongly_agree||0)+(dist.somewhat_agree||0);
    const bottom=(dist.strongly_disagree||0)+(dist.somewhat_disagree||0);
    return {top,bottom,net:top-bottom};
  }
  function metricHtml(s, aud) {
    const netCls=s.net>=0?'positive':'negative';
    const audKey=aud || 'A';
    return `${aud?`<span class="agreement-aud ${aud}">${aud}</span>`:''}`+
      `<span class="agreementmetric pos" data-summary="top" data-aud="${audKey}">T2B <strong>${s.top.toFixed(0)}%</strong></span>`+
      `<span class="agreementmetric net">Net <strong class="${netCls}">${s.net>=0?'+':''}${s.net.toFixed(0)}</strong></span>`+
      `<span class="agreementmetric neg" data-summary="bottom" data-aud="${audKey}">B2B <strong>${s.bottom.toFixed(0)}%</strong></span>`;
  }
  function stackTrack(dist, extraClass, clickCtx) {
    const track=document.createElement('div');
    track.className='stacktrack'+(extraClass?' '+extraClass:'');
    AGREE6_ORDER.forEach(k => {
      const seg=document.createElement('div'); seg.className='stackseg';
      const w=dist[k]||0; seg.style.width=w.toFixed(1)+'%'; seg.style.background=AGREE6_COLORS[k];
      if (w>=7) seg.textContent=w.toFixed(0)+'%';
      seg.title=`${AGREE6_LABELS[k]}: ${w.toFixed(1)}%`;
      if (clickCtx) {
        seg.style.cursor='pointer';
        seg.onclick=()=>{
          const universe=eligibleRows(clickCtx.rows,clickCtx.field);
          const sub=universe.filter(r=>val(r,clickCtx.field)===k);
          showDrilldown(sub, universe, `${clickCtx.label}: ${AGREE6_LABELS[k]}`);
        };
      }
      track.appendChild(seg);
    });
    return track;
  }

  mod.fields.forEach(([field,label]) => {
    const dA=distFor(rowsA,field), sA=summary(dA);
    const row=document.createElement('div'); row.className='agreementrow';
    const head=document.createElement('div'); head.className='agreementhead';
    const lbl=document.createElement('div'); lbl.className='agreementlabel'; lbl.textContent=label; head.appendChild(lbl);
    const sums=document.createElement('div'); sums.className='agreementsummary';
    if (compareOn) {
      const dB=distFor(rowsB,field), sB=summary(dB);
      sums.innerHTML=metricHtml(sA,'A')+metricHtml(sB,'B'); head.appendChild(sums); row.appendChild(head);
      row.appendChild(stackTrack(dA,'comparea'));
      row.appendChild(stackTrack(dB,'compareb'));
    } else {
      sums.innerHTML=metricHtml(sA,''); head.appendChild(sums); row.appendChild(head);
      row.appendChild(stackTrack(dA,'',{rows:rowsA,field,label}));
    }
    const bindAgreementSummary = (audKey, rows) => {
      const universe=eligibleRows(rows,field);
      const topEl=sums.querySelector(`.agreementmetric.pos[data-aud="${audKey}"]`);
      const bottomEl=sums.querySelector(`.agreementmetric.neg[data-aud="${audKey}"]`);
      makeMetricClickable(topEl, universe, r=>['strongly_agree','somewhat_agree'].includes(val(r,field)), `${label}: Top 2 Box${compareOn?` · Audience ${audKey}`:''}`);
      makeMetricClickable(bottomEl, universe, r=>['somewhat_disagree','strongly_disagree'].includes(val(r,field)), `${label}: Bottom 2 Box${compareOn?` · Audience ${audKey}`:''}`);
    };
    bindAgreementSummary('A', rowsA);
    if (compareOn) bindAgreementSummary('B', rowsB);
    vizArea.appendChild(row);
  });

  const bases=mod.fields.map(([field])=>catDist(rowsA,field).n);
  const baseA=bases.length ? Math.min(...bases) : rowsA.length;
  if (compareOn) {
    const basesB=mod.fields.map(([field])=>catDist(rowsB,field).n);
    const baseB=basesB.length ? Math.min(...basesB) : rowsB.length;
    document.getElementById('panelFootnote').textContent=`Base | Audience A: ${baseA} · Audience B: ${baseB}. “Not familiar enough to say” is shown separately and remains in the question base.`;
  } else {
    document.getElementById('panelFootnote').textContent=`Base: ${baseA}. “Not familiar enough to say” is shown separately and remains in the question base. Click any response segment, Top 2 Box or Bottom 2 Box to inspect its demographic profile.`;
  }
}

function renderA2TopicsModule(mod, rowsA, rowsB) {
  const vizArea = document.getElementById('vizArea');

  const chipWrap = document.createElement('div');
  chipWrap.className = 'chipset';
  chipWrap.style.marginBottom = '16px';
  ['All'].concat(TOPCOUNTRY_OPTIONS).forEach(c => {
    const chip = document.createElement('div');
    chip.className = 'chip' + (a2Country===c ? ' sel':'');
    chip.textContent = c === 'All' ? 'All (pooled)' : c;
    chip.onclick = () => { a2Country = c; render(); };
    chipWrap.appendChild(chip);
  });
  vizArea.appendChild(chipWrap);

  const subA = a2Country==='All' ? rowsA : rowsA.filter(r => val(r,'topcountry')===a2Country);
  const subB = compareOn ? (a2Country==='All' ? rowsB : rowsB.filter(r => val(r,'topcountry')===a2Country)) : null;

  const data = mod.fields.map(([field,label]) => ({
    field, label, a: pctFlag(subA, field), b: compareOn ? pctFlag(subB, field) : null,
  }));
  data.sort((x,y) => (y.a||0)-(x.a||0));
  const maxV = 100; // fixed 0-100% basis, not relative to the largest value in view
  data.forEach(d => {
    const row = document.createElement('div'); row.className='barrow';
    if (compareOn) {
      const cA = flagCount(subA, d.field), cB = flagCount(subB, d.field);
      const sig = twoPropSig(cA.count, cA.n, cB.count, cB.n);
      row.innerHTML = `<div class="barlabel">${d.label}</div>
        <div class="bartrack">
          <div class="barfillA" style="width:${(d.a/maxV*100).toFixed(1)}%"></div>
          <div class="barfillB" style="width:${(d.b/maxV*100).toFixed(1)}%"></div>
        </div>
        <div class="barval"><div class="cmpvals"><span class="vA">A ${d.a!==null?d.a.toFixed(0)+'%':'n/a'}</span><span class="vB">B ${d.b!==null?d.b.toFixed(0)+'%':'n/a'}</span></div>${sigSuffix(sig, d.a, d.b)}</div>`;
    } else {
      row.innerHTML = `<div class="barlabel">${d.label}</div>
        <div class="bartrack"><div class="barfillSingle" style="width:${(d.a/maxV*100).toFixed(1)}%"></div></div>
        <div class="barval">${d.a!==null?d.a.toFixed(0)+'%':'n/a'}</div>`;
      makeClickable(row, eligibleRows(subA, d.field), r => val(r, d.field) === 1, d.label);
    }
    vizArea.appendChild(row);
  });

  const baseA = baseNFlag(subA, mod.fields[0][0]);
  const baseB = compareOn ? baseNFlag(subB, mod.fields[0][0]) : null;
  const whoText = a2Country==='All' ? 'everyone, across all top-pick countries' : `people who picked ${a2Country} as their personal top country`;
  document.getElementById('panelFootnote').textContent = compareOn
    ? `Showing ${whoText}. Base | Audience A: ${baseA}  ·  Audience B: ${baseB}`
    : `Showing ${whoText}. Base: ${baseA}${baseA < 50 ? ' (small base, read as directional)' : ''}`;
}

function renderTopicsCompareModule(rowsA) {
  const vizArea = document.getElementById('vizArea');

  const chipWrap = document.createElement('div');
  chipWrap.className = 'chipset';
  chipWrap.style.marginBottom = '16px';
  TOPCOUNTRY_OPTIONS.forEach(c => {
    const chip = document.createElement('div');
    chip.className = 'chip' + (topicsCompareCountry===c ? ' sel':'');
    chip.textContent = displayCountryName(c);
    chip.onclick = () => { topicsCompareCountry = c; render(); };
    chipWrap.appendChild(chip);
  });
  vizArea.appendChild(chipWrap);

  const countryRows = rowsA.filter(r => val(r,'topcountry')===topicsCompareCountry);
  const data = TOPIC_PAIRS.map(([key,label]) => ({
    key, label,
    country: pctFlag(countryRows, 'a2_'+key),
    vietnam: pctFlag(rowsA, 'd3_'+key),
  }));
  data.sort((x,y) => (y.country||0)-(x.country||0));
  const maxV = 100; // fixed 0-100% basis, not relative to the largest value in view

  const legend = document.createElement('div');
  legend.className = 'linelegend';
  legend.style.marginBottom = '10px';
  const compareCountryLabel = displayCountryName(topicsCompareCountry);
  const vietnamLabel = displayCountryName('Vietnam');
  legend.innerHTML = `<span><i style="background:var(--lineB)"></i>${compareCountryLabel}</span><span><i style="background:var(--lineA)"></i>${vietnamLabel}</span><span style="margin-left:4px;color:var(--text-muted)">${currentLang==='vi'?'▲ = cao hơn có ý nghĩa thống kê (95%)':'▲ = significantly higher (95%)'}</span>`;
  vizArea.appendChild(legend);

  data.forEach(d => {
    const row = document.createElement('div'); row.className='barrow';
    const cC = flagCount(countryRows, 'a2_'+d.key), cV = flagCount(rowsA, 'd3_'+d.key);
    const sig = twoPropSig(cC.count, cC.n, cV.count, cV.n);
    row.innerHTML = `<div class="barlabel">${d.label}</div>
      <div class="bartrack">
        <div class="barfillA" style="width:${(d.vietnam/maxV*100).toFixed(1)}%"></div>
        <div class="barfillB" style="width:${(d.country/maxV*100).toFixed(1)}%"></div>
      </div>
      <div class="barval"><div class="cmpvals"><span class="vB">${compareCountryLabel} ${d.country!==null?d.country.toFixed(0)+'%':'n/a'}</span><span class="vA">${vietnamLabel} ${d.vietnam!==null?d.vietnam.toFixed(0)+'%':'n/a'}</span></div>${sigNamedSuffix(sig, d.country, d.vietnam, topicsCompareCountry, 'Vietnam', 'b', 'a', `Significant difference between ${topicsCompareCountry} and Vietnam, 95% confidence`)}</div>`;
    vizArea.appendChild(row);
  });

  const baseCountry = baseNFlag(countryRows, 'a2_food');
  const baseVietnam = baseNFlag(rowsA, 'd3_food');
  document.getElementById('panelFootnote').textContent = currentLang === 'vi'
    ? `${compareCountryLabel} chỉ dựa trên những người trong bộ lọc hiện tại đã chọn quốc gia này là quốc gia họ quan tâm nhất (n=${baseCountry}). Việt Nam dựa trên toàn bộ người trả lời trong bộ lọc hiện tại vì câu hỏi về Việt Nam được hỏi với tất cả người tham gia (n=${baseVietnam}).`
    : `${topicsCompareCountry} is based only on people within the current filters who picked it as their personal top country (n=${baseCountry}). Vietnam is based on everyone within the current filters, since it was asked of all respondents (n=${baseVietnam}).`;
}

function avgNumeric(rows, field) {
  const vals = rows.map(r => val(r,field)).filter(v => v!==null && v!==undefined);
  if (vals.length===0) return null;
  return vals.reduce((s,v)=>s+v,0)/vals.length;
}

function renderCurveModule(mod, rowsA, rowsB) {
  const vizArea = document.getElementById('vizArea');
  if (mod.slotsField) {
    const avgA = avgNumeric(rowsA, mod.slotsField);
    const avgB = compareOn ? avgNumeric(rowsB, mod.slotsField) : null;
    const summary = document.createElement('div');
    summary.className = 'kpi-grid';
    summary.style.marginBottom = '14px';
    summary.innerHTML = `
      <div class="kpi">
        <div class="kval" style="color:var(--lineA);">${avgA!==null?avgA.toFixed(1):'n/a'}</div>
        <div class="klabel">Average number of time-of-day slots watched in${compareOn?', Audience A':''} (out of 9, a usage-intensity proxy since there is no direct "hours watched" question)</div>
        ${compareOn ? `<div class="kvalB">B: ${avgB!==null?avgB.toFixed(1):'n/a'}</div>` : ''}
      </div>
    `;
    vizArea.appendChild(summary);
  }
  const W=880,H=320,padL=44,padR=20,padT=18,padB=34;
  const innerW=W-padL-padR, innerH=H-padT-padB;
  const n = mod.fields.length;
  const seriesA = mod.fields.map(([f]) => pctFlag(rowsA,f));
  const seriesB = compareOn ? mod.fields.map(([f]) => pctFlag(rowsB,f)) : null;
  const allV = seriesA.concat(seriesB||[]).filter(v=>v!==null);
  const maxV = Math.max(...allV, 5) * 1.15;
  function x(i){ return padL + innerW*i/(n-1); }
  function y(v){ return padT + innerH*(1 - v/maxV); }
  let svg = `<svg viewBox="0 0 ${W} ${H}" style="width:100%; max-width:${W}px; height:auto;">`;
  for (let g=0; g<=4; g++) {
    const v = maxV*g/4, gy = y(v);
    svg += `<line x1="${padL}" y1="${gy}" x2="${W-padR}" y2="${gy}" stroke="var(--border)" stroke-width="1"/>`;
    svg += `<text x="${padL-8}" y="${gy+4}" font-size="10" fill="var(--text-muted)" text-anchor="end">${v.toFixed(0)}%</text>`;
  }
  mod.fields.forEach(([f,lbl],i) => { svg += `<text x="${x(i)}" y="${H-padB+18}" font-size="9.5" fill="var(--text-secondary)" text-anchor="middle">${lbl}</text>`; });
  function drawLine(series,color) {
    let pts = series.map((v,i)=> v!==null?`${x(i)},${y(v)}`:null).filter(Boolean).join(' ');
    svg += `<polyline points="${pts}" fill="none" stroke="${color}" stroke-width="2.4" stroke-linejoin="round" stroke-linecap="round"/>`;
    series.forEach((v,i)=>{ if(v!==null) svg += `<circle cx="${x(i)}" cy="${y(v)}" r="3" fill="${color}"/>`; });
  }
  drawLine(seriesA,'var(--lineA)');
  if (seriesB) drawLine(seriesB,'var(--lineB)');
  svg += `</svg>`;
  const legend = document.createElement('div'); legend.className='linelegend';
  legend.innerHTML = `<span><i style="background:var(--lineA)"></i>Audience A</span>` + (compareOn ? `<span><i style="background:var(--lineB)"></i>Audience B</span>` : '');
  vizArea.appendChild(legend);
  const wrap = document.createElement('div'); wrap.innerHTML = svg; vizArea.appendChild(wrap);

  const noneA = pctFlag(rowsA, mod.noneField);
  const noneB = compareOn ? pctFlag(rowsB, mod.noneField) : null;
  document.getElementById('panelFootnote').textContent = `${mod.noneLabel} | Audience A: ${noneA!==null?noneA.toFixed(0)+'%':'n/a'}` + (compareOn?`  ·  Audience B: ${noneB!==null?noneB.toFixed(0)+'%':'n/a'}`:'');
}

function recallYesPct(rows) {
  const d = catDist(rows, 'recall');
  return d.n > 0 ? (d.dist.once||0) + (d.dist.several||0) : null;
}
function sentimentTop2Pct(rows) {
  const d = catDist(rows, 'sentiment');
  return d.n > 0 ? (d.dist.pos_mostly||0) + (d.dist.pos_more||0) : null;
}
function sentimentBottom2Pct(rows) {
  const d = catDist(rows, 'sentiment');
  return d.n > 0 ? (d.dist.neg_more||0) + (d.dist.neg_mostly||0) : null;
}
function sentimentNetScore(rows) {
  const pos = sentimentTop2Pct(rows), neg = sentimentBottom2Pct(rows);
  return (pos===null || neg===null) ? null : Math.round((pos-neg)*10)/10;
}


function renderVntdFunnel(rowsA, rowsB) {
  const area = document.getElementById('vizArea');
  const stages = [
    { field:'vaware', label:'Aware of Vietnam Today' },
    { field:'vviewer', label:'Has watched Vietnam Today' },
    { field:'vrecent', label:'Watched within past week' }
  ];
  function stats(rows, field) {
    const c = flagCount(rows, field);
    return { n:c.n, count:c.count, pct:c.n ? c.count/c.n*100 : null };
  }
  function one(rows, cls, audienceLabel) {
    const st = stages.map(s => ({...s, ...stats(rows,s.field)}));
    const awareCount = st[0].count || 0;
    const viewerCount = st[1].count || 0;
    const recentCount = st[2].count || 0;
    const convAwareViewer = awareCount ? viewerCount/awareCount*100 : null;
    const convViewerRecent = viewerCount ? recentCount/viewerCount*100 : null;
    const awarePct = st[0].pct || 0;
    let body = `<div class="vntd-funnel-card"><div class="vntd-funnel-head"><div class="vntd-funnel-aud">${audienceLabel}</div><div class="vntd-funnel-base">Base n = ${rows.length.toLocaleString()}</div></div>`;
    st.forEach((s,i)=>{
      const rel = awarePct>0 && s.pct!==null ? Math.max(38, s.pct/awarePct*100) : 38;
      body += `<div class="vntd-funnel-stage ${cls}" data-funnel-field="${s.field}" data-funnel-label="${s.label.replace(/"/g,'&quot;')}" style="width:${Math.min(100,rel).toFixed(1)}%"><div class="stage-line"><span class="stage-label">${s.label}</span><span class="stage-pct">${s.pct!==null?s.pct.toFixed(1)+'%':'n/a'}</span></div><div class="stage-n">Answer n = ${s.count.toLocaleString()} / Base n = ${s.n.toLocaleString()}</div></div>`;
      if (i===0) body += `<div class="vntd-funnel-conv">↓ <strong>${convAwareViewer!==null?convAwareViewer.toFixed(1)+'%':'n/a'}</strong></div>`;
      if (i===1) body += `<div class="vntd-funnel-conv">↓ <strong>${convViewerRecent!==null?convViewerRecent.toFixed(1)+'%':'n/a'}</strong></div>`;
    });
    body += `<div class="vntd-funnel-summary"><div class="metric"><strong>${convAwareViewer!==null?convAwareViewer.toFixed(1)+'%':'n/a'}</strong><span>Aware of Vietnam Today → Has watched Vietnam Today</span></div><div class="metric"><strong>${convViewerRecent!==null?convViewerRecent.toFixed(1)+'%':'n/a'}</strong><span>Has watched Vietnam Today → Watched within past week</span></div></div><div class="vntd-funnel-note">Bars are scaled relative to Vietnam Today awareness within each selected audience. Percentages remain based on the eligible base for each measure.</div></div>`;
    return body;
  }
  area.innerHTML = `<div class="vntd-funnel-wrap ${compareOn?'compare':''}">${one(rowsA,'A','Audience A')}${compareOn?one(rowsB,'B','Audience B'):''}</div>`;
  area.querySelectorAll('.vntd-funnel-stage').forEach(el=>{
    const field=el.dataset.funnelField, label=el.dataset.funnelLabel;
    const rows = el.classList.contains('B') ? rowsB : rowsA;
    makeClickable(el, eligibleRows(rows,field), r=>val(r,field)===1, label);
  });
  document.getElementById('panelFootnote').textContent = `Base | Audience A: ${rowsA.length}` + (compareOn ? ` · Audience B: ${rowsB.length}` : '');
}

function renderKPIs(rowsA, rowsB) {
  const vizArea = document.getElementById('vizArea');
  const segmentNames = (FILTER_DEFS.find(f => f.key==='segment') || {}).names || {};
  const segmentShare = seg => rows => {
    const d = catDist(rows, 'segment');
    return d.n > 0 ? (d.dist[seg] || 0) : null;
  };
  const pctCats = (rows, field, cats) => {
    const d = catDist(rows, field);
    return d.n > 0 ? cats.reduce((sum,c)=>sum+(d.dist[c]||0),0) : null;
  };
  const groups = [
    {
      title:'Vietnam Today performance',
      items:[
        { label:'Aware of Vietnam Today', field:'vaware' },
        { label:'Has watched Vietnam Today', field:'vviewer' },
        { label:'Watched within past week', field:'vrecent' },
      ]
    },
    {
      title:'Vietnam market context',
      items:[
        { label:'Saw Vietnam news/content in past month', compute:recallYesPct, predicate:r=>['once','several'].includes(val(r,'recall')), eligField:'recall' },
        { label:'Saw mostly positive Vietnam news', compute:sentimentTop2Pct, polarity:'pos', predicate:r=>['pos_mostly','pos_more'].includes(val(r,'sentiment')), eligField:'sentiment' },
        { label:'Interested in Vietnam', field:'a1_vietnam' },
      ]
    },
    {
      title:'Audience potential & experience',
      items:[
        { label:'Willing to watch Vietnam Today', compute:rows=>pctCats(rows,'c15',['def_would','prob_would']), predicate:r=>['def_would','prob_would'].includes(val(r,'c15')), eligField:'c15' },
        { label:'Vietnam Today helps understand Vietnam', compute:rows=>pctCats(rows,'vntd_understanding',['verymuch','quitebit']), predicate:r=>['verymuch','quitebit'].includes(val(r,'vntd_understanding')), eligField:'vntd_understanding' },
        { label:'Intend to continue watching', compute:rows=>pctCats(rows,'vntd_keepwatching',['def_continue','prob_continue']), predicate:r=>['def_continue','prob_continue'].includes(val(r,'vntd_keepwatching')), eligField:'vntd_keepwatching' },
      ]
    },
    {
      title:'Priority audiences',
      items:[
        { label:'Influential audience', field:'infl' },
        { label:segmentNames.enthusiasts || 'Vietnam Enthusiasts', compute:segmentShare('enthusiasts'), predicate:r=>val(r,'segment')==='enthusiasts', eligField:'segment', clickLabel:segmentNames.enthusiasts || 'Vietnam Enthusiasts' },
        { label:'Personal connection to Vietnam', field:'conn' },
      ]
    }
  ];

  function fmt(v, k) {
    if (v === null) return 'n/a';
    if (k.isScore) return (v>=0?'+':'') + v.toFixed(0);
    return v.toFixed(0) + '%';
  }
  function makeKPI(k) {
    const a = k.compute ? k.compute(rowsA) : pctFlag(rowsA, k.field);
    const div = document.createElement('div'); div.className='kpi';
    let colorOverride = '';
    if (k.polarity) colorOverride = `style="color:var(--${k.polarity === 'pos' ? 'posB' : 'negB'});"`;
    else if (k.isScore && a !== null) colorOverride = `style="color:var(--${a>=0?'posB':'negB'});"`;
    div.innerHTML = `<div class="kval" ${colorOverride}>${fmt(a,k)}</div><div class="klabel">${k.label}</div>` + (compareOn ? `<div class="kvalB">B: ${(()=>{const b=k.compute ? k.compute(rowsB) : pctFlag(rowsB,k.field);return fmt(b,k);})()}</div>` : '');
    const clickPredicate = k.predicate || (k.field ? (r => val(r, k.field) === 1) : null);
    if (!compareOn && clickPredicate) {
      const eligField = k.eligField || k.field;
      const universe = eligField ? eligibleRows(rowsA, eligField) : rowsA;
      makeClickable(div, universe, clickPredicate, k.clickLabel || k.label);
    }
    return div;
  }

  const groupsWrap = document.createElement('div');
  groupsWrap.className = 'kpi-groups';
  groups.forEach(g => {
    const box = document.createElement('section'); box.className='kpi-group';
    const head = document.createElement('div'); head.className='kpi-group-head';
    head.innerHTML = `<div class="kpi-group-title"><span class="group-dot"></span><span>${g.title}</span></div>`;
    box.appendChild(head);
    const grid = document.createElement('div'); grid.className='kpi-grid';
    g.items.forEach(k => grid.appendChild(makeKPI(k)));
    box.appendChild(grid);
    groupsWrap.appendChild(box);
  });
  vizArea.appendChild(groupsWrap);
  document.getElementById('panelFootnote').textContent = '';
}

function realCountryN(countryCode) {
  return countryCode === 'TOTAL' ? ROWS.length : ROWS.filter(r => val(r,'country')===countryCode).length;
}

function renderScreenerTargetPanel(suffix, target) {
  const wrap = document.getElementById('screenerChips_' + suffix);
  wrap.innerHTML = '';
  SCREENER.order.forEach(code => {
    const chip = document.createElement('div');
    chip.className = 'chip' + (target.country===code ? ' sel':'');
    chip.textContent = SCREENER.names[code];
    chip.onclick = () => { target.country = code; render(); };
    wrap.appendChild(chip);
  });
  if (target.base === 'all') {
    const n = SCREENER.base_n[target.country];
    document.getElementById('screenerN_' + suffix).textContent = n ? `n = ${n.total} responses, ${n.complete} completes` : '';
  } else {
    const realN = realCountryN(target.country);
    document.getElementById('screenerN_' + suffix).textContent = `n = ${realN} completed interviews (final data)`;
  }

  const bt = document.getElementById('screenerBaseToggle_' + suffix);
  bt.innerHTML = '';
  [['all', `All respondents (${SCREENER.base_n.TOTAL.total.toLocaleString()})`], ['completes', `Completed interviews only (${ROWS.length.toLocaleString()})`]].forEach(([v,l]) => {
    const t = document.createElement('div');
    t.className = 'tri' + (target.base===v ? ' sel':'');
    t.textContent = l;
    t.onclick = () => { target.base = v; render(); };
    bt.appendChild(t);
  });
}

function pctFlagCountry(field, countryCode) {
  const rows = countryCode==='TOTAL' ? ROWS : ROWS.filter(r => val(r,'country')===countryCode);
  return pctFlag(rows, field);
}

function screenerTargetLabel(target) {
  return `${SCREENER.names[target.country]} · ${target.base==='all' ? 'all respondents' : 'completes only'}`;
}

function screenerValue(mod, target, itemLabel) {
  if (target.base === 'all') {
    const data = SCREENER[mod.dataKey];
    return data[itemLabel][target.country];
  }
  return pctFlagCountry(mod.fieldMap[itemLabel], target.country);
}

function screenerFullScaleFor(field, dataKey, target) {
  if (target.base === 'all') {
    const shortname = field.replace(/^r_/, '').replace(/^a1_/, '');
    const scaleObj = dataKey === 'S8' ? SCREENER.S8_scale[shortname] : SCREENER.A1_scale[shortname];
    const d = scaleObj ? scaleObj[target.country] : null;
    const out = {};
    SCALE5_ORDER.forEach(k => { out[k] = (d && d[k]!==null && d[k]!==undefined) ? d[k] : 0; });
    return out;
  }
  const scaleField = field + '_scale';
  const rows = target.country === 'TOTAL' ? ROWS : ROWS.filter(r => val(r,'country')===target.country);
  const dist = catDist(rows, scaleField);
  const out = {};
  SCALE5_ORDER.forEach(k => { out[k] = dist.dist[k] || 0; });
  return out;
}

function renderScreenerFullScale(mod) {
  const vizArea = document.getElementById('vizArea');
  const legend = document.createElement('div');
  legend.className = 'scalelegend';
  legend.innerHTML = SCALE5_ORDER.map(k => `<span><i style="background:${SCALE5_COLORS[k]}"></i>${SCALE5_LABELS[k]}</span>`).join('');
  vizArea.appendChild(legend);

  function stackTrack(dist, extraClass, clickCtx) {
    const track = document.createElement('div');
    track.className = 'stacktrack' + (extraClass ? ' '+extraClass : '');
    SCALE5_ORDER.forEach(k => {
      const seg = document.createElement('div');
      seg.className = 'stackseg';
      const w = dist[k];
      seg.style.width = w.toFixed(1) + '%';
      seg.style.background = SCALE5_COLORS[k];
      if (w >= 7) seg.textContent = w.toFixed(0) + '%';
      if (clickCtx) {
        seg.style.cursor = 'pointer';
        seg.onclick = () => {
          const cvf = clickCtx.valFn || val;
          const subRows = clickCtx.universeRows.filter(r => cvf(r, clickCtx.field) === k);
          showDrilldown(subRows, clickCtx.universeRows, `${clickCtx.itemLabel}: ${SCALE5_LABELS[k]}`, !!clickCtx.isScreenerPop);
        };
      }
      track.appendChild(seg);
    });
    return track;
  }

  const items = Object.keys(mod.fieldMap).map(label => {
    const field = mod.fieldMap[label];
    const dA = screenerFullScaleFor(field, mod.dataKey, screenerTargetA);
    return { label, dA };
  });
  items.sort((x,y) => (y.dA.vi+y.dA.i) - (x.dA.vi+x.dA.i));

  items.forEach(({label,dA}) => {
    const field = mod.fieldMap[label];
    const wrap = document.createElement('div');
    wrap.className = 'stackrow';
    const t2bA = (dA.vi+dA.i).toFixed(0), b2bA = (dA.sli+dA.na).toFixed(0);
    if (screenerCompareOn) {
      const dB = screenerFullScaleFor(field, mod.dataKey, screenerTargetB);
      const t2bB = (dB.vi+dB.i).toFixed(0), b2bB = (dB.sli+dB.na).toFixed(0);
      const head = document.createElement('div');
      head.className = 'stacklabel';
      head.innerHTML = `<span>${label}</span><span class="scale-summary"><span class="scale-pair A"><span class="aud">A</span><span class="metric">T2B <strong>${t2bA}%</strong></span><span class="metric">B2B <strong>${b2bA}%</strong></span></span><span class="scale-pair B"><span class="aud">B</span><span class="metric">T2B <strong>${t2bB}%</strong></span><span class="metric">B2B <strong>${b2bB}%</strong></span></span></span>`;
      wrap.appendChild(head);
      wrap.appendChild(stackTrack(dA));
      wrap.appendChild(stackTrack(dB, 'compareb'));
    } else {
      const head = document.createElement('div');
      head.className = 'stacklabel';
      head.innerHTML = `<span>${label}</span><span class="scale-summary"><span class="scale-pair A"><span class="metric">T2B <strong>${t2bA}%</strong></span><span class="metric">B2B <strong>${b2bA}%</strong></span></span></span>`;
      wrap.appendChild(head);
      let clickCtx = null;
      if (screenerTargetA.base === 'completes') {
        const universeRows = screenerTargetA.country === 'TOTAL' ? ROWS : ROWS.filter(r => val(r,'country')===screenerTargetA.country);
        clickCtx = { field: field + '_scale', universeRows, itemLabel: label };
      } else {
        const shortname = field.replace(/^r_/, '').replace(/^a1_/, '');
        const universeRows = screenerTargetA.country === 'TOTAL' ? SCREENER_ROWS : SCREENER_ROWS.filter(r => sval(r,'country')===screenerTargetA.country);
        clickCtx = { field: (mod.dataKey==='S8' ? 'r_' : 'a1_') + shortname + '_scale', universeRows, itemLabel: label, valFn: sval, isScreenerPop: true };
      }
      wrap.appendChild(stackTrack(dA, null, clickCtx));
    }
    vizArea.appendChild(wrap);
  });

  document.getElementById('panelFootnote').textContent = screenerCompareOn
    ? `Target A: ${screenerTargetLabel(screenerTargetA)}  ·  Target B: ${screenerTargetLabel(screenerTargetB)}`
    : `Base | ${screenerTargetLabel(screenerTargetA)}. Click a segment of any bar to see its demographic profile below.`;
}



// ---------------- VIETNAM TODAY VIEWER TOUCHPOINTS ----------------
let vntdTouchpointView='groups';
const VNTD_TOUCHPOINT_FIELDS=[
  ['vntd_seen_tv','On TV (cable, satellite, or OTT)'],
  ['vntd_seen_amasian','Amasian TV'],['vntd_seen_toober','Toober'],['vntd_seen_channelbox','ChannelBox'],
  ['vntd_seen_abc','ABC'],['vntd_seen_singtel','Singtel'],['vntd_seen_cgtn','CGTN'],['vntd_seen_guangxi','Guangxi RTV'],
  ['vntd_seen_myasiatv','MyAsiaTV'],['vntd_seen_arirang','Arirang TV'],['vntd_seen_kbs','KBS'],
  ['vntd_seen_vtvgo','VTVGo app'],['vntd_seen_vntd_app','Vietnam Today app'],['vntd_seen_vntd_web','Vietnam Today website'],
  ['vntd_seen_youtube','YouTube'],['vntd_seen_facebook','Facebook'],['vntd_seen_tiktok','TikTok'],['vntd_seen_instagram','Instagram'],
  ['vntd_seen_other','Other']
];
const VNTD_TOUCHPOINT_GROUPS=[
  {key:'tv',label:'TV / channel distribution',fields:['vntd_seen_tv','vntd_seen_amasian','vntd_seen_toober','vntd_seen_channelbox','vntd_seen_abc','vntd_seen_singtel','vntd_seen_cgtn','vntd_seen_guangxi','vntd_seen_myasiatv','vntd_seen_arirang','vntd_seen_kbs']},
  {key:'owned',label:'Vietnam Today / VTV-owned digital',fields:['vntd_seen_vtvgo','vntd_seen_vntd_app','vntd_seen_vntd_web']},
  {key:'social',label:'Social / video platforms',fields:['vntd_seen_youtube','vntd_seen_facebook','vntd_seen_tiktok','vntd_seen_instagram']},
  {key:'other',label:'Other',fields:['vntd_seen_other']}
];
function touchpointQuestionBase(rows){ return rows.filter(r=>{ const v=val(r,'vntd_seen_tv'); return v===0||v===1; }); }
function touchpointGroupSelected(r, fields){ return fields.some(f=>val(r,f)===1); }
function touchpointEligibleForFields(rows, fields){
  return rows.filter(r=>fields.some(f=>fieldMarketEligible(r,f)));
}
function touchpointStats(rows, fields){
  const elig=touchpointEligibleForFields(rows,fields); const count=elig.filter(r=>touchpointGroupSelected(r,fields)).length;
  return {elig,count,pct:elig.length?count/elig.length*100:null};
}
function renderTouchpointBar(target,label,fields,rowsA,rowsB){
  const a=touchpointStats(rowsA,fields), b=compareOn?touchpointStats(rowsB,fields):null;
  const row=document.createElement('div'); row.className='barrow';
  if(compareOn){
    const sig=twoPropSig(a.count,a.elig.length,b.count,b.elig.length);
    row.innerHTML=`<div class="barlabel">${label}</div><div class="bartrack"><div class="barfillA" style="width:${(a.pct||0).toFixed(1)}%"></div><div class="barfillB" style="width:${(b.pct||0).toFixed(1)}%"></div></div><div class="barval"><div class="cmpvals"><span class="vA">A ${a.pct===null?'n/a':a.pct.toFixed(0)+'%'}</span><span class="vB">B ${b.pct===null?'n/a':b.pct.toFixed(0)+'%'}</span></div>${sigSuffix(sig,a.pct,b.pct)}</div>`;
    makeMetricClickable(row.querySelector('.vA'),a.elig,r=>touchpointGroupSelected(r,fields),`${label} · Audience A`);
    makeMetricClickable(row.querySelector('.vB'),b.elig,r=>touchpointGroupSelected(r,fields),`${label} · Audience B`);
  } else {
    row.innerHTML=`<div class="barlabel">${label}</div><div class="bartrack"><div class="barfillSingle" style="width:${(a.pct||0).toFixed(1)}%"></div></div><div class="barval">${a.pct===null?'n/a':a.pct.toFixed(0)+'%'}</div>`;
    makeClickable(row,a.elig,r=>touchpointGroupSelected(r,fields),label);
  }
  target.appendChild(row);
}
function renderVntdTouchpointsModule(mod, rowsA, rowsB){
  const viz=document.getElementById('vizArea');
  const ctl=document.createElement('div'); ctl.className='viewer-profile-toolbar';
  const box=document.createElement('div'); box.className='driver-control'; box.innerHTML='<label>View</label>';
  const toggles=document.createElement('div'); toggles.className='viewer-profile-toggle';
  [['groups','Channel groups'],['detail','Detailed platforms']].forEach(([key,label])=>{
    const b=document.createElement('button'); b.type='button'; b.textContent=label; b.className=key===vntdTouchpointView?'active':'';
    b.onclick=(e)=>{e.preventDefault();vntdTouchpointView=key;render();}; toggles.appendChild(b);
  });
  box.appendChild(toggles); ctl.appendChild(box); viz.appendChild(ctl);
  const intro=document.createElement('p'); intro.className='desc';
  intro.textContent = vntdTouchpointView==='groups'
    ? 'Channel groups show the share of eligible viewers who saw Vietnam Today through at least one touchpoint in each distribution family. Categories can overlap.'
    : 'Detailed platforms are rebased to Vietnam Today viewers in markets where each route or platform operates. Unavailable markets are excluded from the denominator. This is a multi-select question, so percentages can total more than 100%.';
  viz.appendChild(intro);
  const rows=document.createElement('div'); rows.className='touchpoint-bars'; viz.appendChild(rows);
  if(vntdTouchpointView==='groups'){
    VNTD_TOUCHPOINT_GROUPS.forEach(g=>renderTouchpointBar(rows,g.label,g.fields,rowsA,rowsB));
  } else {
    const detail=VNTD_TOUCHPOINT_FIELDS.map(([f,l])=>({f,l,st:touchpointStats(rowsA,[f])})).sort((x,y)=>(y.st.pct||0)-(x.st.pct||0));
    detail.forEach(d=>renderTouchpointBar(rows,d.l,[d.f],rowsA,rowsB));
  }
  const a=touchpointQuestionBase(rowsA).length, b=compareOn?touchpointQuestionBase(rowsB).length:null;
  document.getElementById('panelFootnote').textContent=compareOn
    ? `Question base: Vietnam Today viewers · Audience A n=${a.toLocaleString()} · Audience B n=${b.toLocaleString()}. Each detailed route uses only viewers in markets where it operates; channel-family bases follow the markets where at least one route in that family is available. Multi-select; categories can overlap.`
    : `Question base: Vietnam Today viewers · n=${a.toLocaleString()}. Each detailed route uses only viewers in markets where it operates; channel-family bases follow the markets where at least one route in that family is available. Multi-select; categories can overlap.`;
}

