function viewerProfileButton(label,key,current,onClick,extraClass=''){
  const b=document.createElement('button'); b.type='button'; b.textContent=label;
  b.className=(key===current?'active ':'')+extraClass; b.onclick=(e)=>{e.preventDefault();onClick(key);}; return b;
}
function renderViewerProfileModule(mod, rowsA, rowsB){
  const viz=document.getElementById('vizArea');
  if(!compareOn) viewerProfileAudience='A';
  const universe=(compareOn && viewerProfileAudience==='B')?rowsB:rowsA;
  const viewers=universe.filter(r=>viewerProfilePopulation==='recent'?val(r,'vrecent')===1:val(r,'vviewer')===1);
  const toolbar=document.createElement('div'); toolbar.className='viewer-profile-toolbar';
  const popCtl=document.createElement('div'); popCtl.className='driver-control'; popCtl.innerHTML='<label>Viewer population</label>';
  const popWrap=document.createElement('div'); popWrap.className='viewer-profile-toggle';
  popWrap.appendChild(viewerProfileButton('All viewers','all',viewerProfilePopulation,k=>{viewerProfilePopulation=k;render();}));
  popWrap.appendChild(viewerProfileButton('Recent viewers','recent',viewerProfilePopulation,k=>{viewerProfilePopulation=k;render();})); popCtl.appendChild(popWrap); toolbar.appendChild(popCtl);
  if(compareOn){
    const audCtl=document.createElement('div'); audCtl.className='driver-control'; audCtl.innerHTML='<label>Analyze audience</label>';
    const audWrap=document.createElement('div'); audWrap.className='viewer-profile-toggle';
    audWrap.appendChild(viewerProfileButton('Audience A','A',viewerProfileAudience,k=>{viewerProfileAudience=k;render();},'A'));
    audWrap.appendChild(viewerProfileButton('Audience B','B',viewerProfileAudience,k=>{viewerProfileAudience=k;render();},'B')); audCtl.appendChild(audWrap); toolbar.appendChild(audCtl);
  }
  viz.appendChild(toolbar);
  const share=universe.length?viewers.length/universe.length*100:0;
  const kpi=document.createElement('div'); kpi.className='viewer-profile-kpi';
  kpi.innerHTML=`<div><span class="desc">${viewerProfilePopulation==='recent'?'Recent viewers':'All viewers'}</span><br><strong>n=${viewers.length.toLocaleString()}</strong></div><div><span class="desc">Share of selected audience</span><br><strong>${share.toFixed(1)}%</strong></div><div><span class="desc">Benchmark universe</span><br><strong>n=${universe.length.toLocaleString()}</strong></div>`; viz.appendChild(kpi);
  const note=document.createElement('p'); note.className='desc'; note.innerHTML='<em>idx</em> compares the viewer profile with the selected-audience benchmark (100 = same profile; above 100 = over-represented; below 100 = under-represented). ▲ / ▼ indicates a statistically significant difference at 95% confidence.'; viz.appendChild(note);
  const grid=document.createElement('div'); grid.className='viewer-profile-grid';
  function addDim(title, rows){ const d=document.createElement('div'); d.className='drilldim'; d.innerHTML=`<h4>${title}</h4>`; rows.forEach(r=>d.appendChild(r)); grid.appendChild(d); }
  addDim('Country', Object.keys(DRILL_COUNTRY_NAMES).map(c=>drillCatRow('Country',viewers,universe,'country',c,DRILL_COUNTRY_NAMES)));
  addDim('Age', ['18-24','25-34','35-44','45-54'].map(c=>drillCatRow('Age',viewers,universe,'age',c,null)));
  addDim('Gender', ['M','F'].map(c=>drillCatRow('Gender',viewers,universe,'gender',c,DRILL_GENDER_NAMES)));
  addDim('Household income', ['L','M','H'].map(c=>drillCatRow('Income',viewers,universe,'income',c,DRILL_INCOME_NAMES)));
  addDim('Relationship with Vietnam', [
    drillFlagRow('Personal connection to Vietnam',viewers,universe,'conn'),
    drillFlagRow('Vietnam origin (born/family)',viewers,universe,'origin'),
    drillFlagRow('Has travelled to Vietnam',viewers,universe,'traveled_vietnam'),
    drillFlagRow('Near-term visit intent (within 3 years)',viewers,universe,'visit_nearterm'),
    drillFlagRow('Comfortable using English (top 2 box)',viewers,universe,'s6_comfort_top2')
  ]);
  addDim('Influential profiles', [
    drillFlagRow('Business & investment',viewers,universe,'influential_business_investment'),
    drillFlagRow('Government / policy',viewers,universe,'f1_gov'),
    drillFlagRow('Content creators / media professionals',viewers,universe,'f1_creator')
  ]);
  addDim('Audience mindsets', ['enthusiasts','explorers','loyalists','disengaged'].map(c=>drillCatRow('Mindset',viewers,universe,'segment',c,{enthusiasts:'Vietnam Enthusiasts',explorers:'Global Explorers',loyalists:'Vietnam Focused',disengaged:'Disengaged'})));
  viz.appendChild(grid);
  document.getElementById('panelFootnote').textContent = `Profile base: ${viewers.length.toLocaleString()} ${viewerProfilePopulation==='recent'?'recent viewers':'viewers'} · benchmark: ${universe.length.toLocaleString()} respondents in the selected audience.`;
}

