let platformProfileDimKey='age';
let platformMatrixDimKey='age';
let platformAudienceKey='A';

const PLATFORM_FIELDS = [
  ['plat_YouTube','YouTube'],['plat_Facebook','Facebook'],['plat_Instagram','Instagram'],['plat_WhatsApp','WhatsApp'],
  ['plat_X_Twitter','X / Twitter'],['plat_TikTok','TikTok'],['plat_Telegram','Telegram'],['plat_LinkedIn','LinkedIn'],
  ['plat_Reddit','Reddit'],['plat_Snapchat','Snapchat'],['plat_Threads','Threads'],['plat_Dailymotion','Dailymotion'],
  ['plat_Discord','Discord'],['plat_RedNote','RedNote (Xiaohongshu)'],['plat_WeChat','WeChat'],['plat_Weibo','Weibo'],
  ['plat_Douyin','Douyin'],['plat_Bilibili','Bilibili'],['plat_Kuaishou','Kuaishou'],['plat_Zhihu','Zhihu'],
  ['plat_Youku','Youku'],['plat_ShareChat','ShareChat'],['plat_Moj','Moj'],['plat_KakaoTalk','KakaoTalk'],['plat_NaverBlog','Naver Blog/Café']
];
const PLATFORM_OPTIONS = PLATFORM_FIELDS.map(([key,label])=>({key,label}));
const PLATFORM_DIMS = [
  { key:'country', label:'Country', cats:[['AU','Australia'],['CA','Canada'],['CN','China'],['FR','France'],['IN','India'],['KR','South Korea'],['SG','Singapore'],['UK','United Kingdom'],['US','United States']], test:(r,k)=>val(r,'country')===k },
  { key:'age', label:'Age', cats:[['18-24','18–24'],['25-34','25–34'],['35-44','35–44'],['45-54','45–54']], test:(r,k)=>val(r,'age')===k },
  { key:'gender', label:'Gender', cats:[['M','Male'],['F','Female']], test:(r,k)=>val(r,'gender')===k },
  { key:'income', label:'Household income', cats:[['L','Lower income'],['M','Middle income'],['H','Higher income']], test:(r,k)=>val(r,'income')===k },
  { key:'urbanicity', label:'Where they live', cats:[['capital','Capital city'],['hub','Major economic hub'],['other','Other city/town']], test:(r,k)=>val(r,'s2_urbanicity')===k },
  { key:'english', label:'English proficiency', cats:[['high','Comfortable using English'],['low','Lower English comfort']], test:(r,k)=>k==='high'?val(r,'s6_comfort_top2')===1:val(r,'s6_comfort_top2')===0 },
  { key:'connection', label:'Personal connection to Vietnam', cats:[['yes','Has personal connection'],['no','No personal connection']], test:(r,k)=>k==='yes'?val(r,'conn')===1:val(r,'conn')===0 },
  { key:'origin', label:'Vietnam origin', cats:[['yes','Vietnam origin (born/family)'],['no','No Vietnam origin']], test:(r,k)=>k==='yes'?val(r,'origin')===1:val(r,'origin')===0 },
  { key:'travelled', label:'Travelled to Vietnam', cats:[['yes','Has travelled to Vietnam'],['no','Has not travelled to Vietnam']], test:(r,k)=>k==='yes'?val(r,'traveled_vietnam')===1:val(r,'traveled_vietnam')===0 },
  { key:'visitintent', label:'Near-term visit intent', cats:[['yes','Plans to visit within 3 years'],['no','No near-term visit intent']], test:(r,k)=>k==='yes'?val(r,'visit_nearterm')===1:val(r,'visit_nearterm')===0 },
  { key:'familiarity', label:'Familiarity with Vietnam', cats:[['alot','Know a lot'],['fair','Know a fair amount'],['little','Know very little'],['nameonly','Only heard of it by name']], test:(r,k)=>val(r,'d1_familiarity')===k },
  { key:'segment', label:'Audience mindset', cats:[['enthusiasts','Vietnam Enthusiasts'],['explorers','Global Explorers'],['loyalists','Vietnam Focused'],['disengaged','Disengaged']], test:(r,k)=>val(r,'segment')===k },
  { key:'influencer_profiles', label:'Influential profiles', cats:[['biz','Business decision-makers'],['invest','Investors'],['gov','Government / policy officials'],['creator','Content creators / media professionals'],['noninfl','Non-influential']], test:(r,k)=>{
      const fmap={biz:'f1_biz',invest:'f1_invest',gov:'f1_gov',creator:'f1_creator'};
      if(k==='noninfl') return ['f1_biz','f1_invest','f1_gov','f1_creator'].every(f=>val(r,f)!==1);
      return fmap[k] && val(r,fmap[k])===1;
    } }
];
function platformDim(key){ return PLATFORM_DIMS.find(x=>x.key===key)||PLATFORM_DIMS[0]; }
function platformLabel(key){ const p=PLATFORM_OPTIONS.find(x=>x.key===key); return p?p.label:key; }
function platformUniverse(rows, field){ return fieldEligibleRows(rows,field); }
function platformUsers(rows, field){ return platformUniverse(rows,field).filter(r=>val(r,field)===1); }
function platformProfileStat(universe, users, dim, catKey){
  const segmentUniverse=universe.filter(r=>dim.test(r,catKey));
  const segmentUsers=segmentUniverse.filter(r=>users.includes(r));
  const segmentN=segmentUniverse.length;
  const userN=segmentUsers.length;
  const benchmarkPct=universe.length?users.length/universe.length*100:null;
  const reachPct=segmentN?userN/segmentN*100:null;
  const idx=(reachPct!==null && benchmarkPct>0)?Math.round(reachPct/benchmarkPct*100):null;
  const sig=(segmentN>0 && universe.length>segmentN)?computeIndexSig(segmentN,userN,universe.length,users.length).sig:false;
  return {segmentN,userN,benchmarkPct,reachPct,idx,sig,segmentUniverse,segmentUsers};
}
function platformAudienceRows(rowsA,rowsB){
  if(!compareOn){ platformAudienceKey='A'; return rowsA; }
  return platformAudienceKey==='B'?rowsB:rowsA;
}
function platformAudienceToggle(container){
  if(!compareOn) return;
  const ctl=document.createElement('div'); ctl.className='driver-control'; ctl.innerHTML='<label>Analyze audience</label>';
  const wrap=document.createElement('div'); wrap.className='driver-audtoggle';
  ['A','B'].forEach(k=>{ const b=document.createElement('button'); b.type='button'; b.className=`driver-audbtn ${platformAudienceKey===k?'active '+k:''}`; b.textContent=`Audience ${k}`; b.onclick=(e)=>{e.preventDefault();platformAudienceKey=k;render();}; wrap.appendChild(b); });
  ctl.appendChild(wrap); container.appendChild(ctl);
}
function renderPlatformProfileModule(rowsA,rowsB){
  const viz=document.getElementById('vizArea');
  const rows=platformAudienceRows(rowsA,rowsB), dim=platformDim(platformProfileDimKey), field=platformProfileKey;
  const universe=platformUniverse(rows,field), users=platformUsers(rows,field);
  const toolbar=document.createElement('div'); toolbar.className='driver-toolbar';
  platformAudienceToggle(toolbar);
  toolbar.appendChild(driverSelect('Platform',platformProfileKey,PLATFORM_OPTIONS,v=>{platformProfileKey=v;render();}));
  toolbar.appendChild(driverSelect('Audience dimension',platformProfileDimKey,PLATFORM_DIMS,v=>{platformProfileDimKey=v;render();}));
  const reach=universe.length?users.length/universe.length*100:null;
  const box=document.createElement('div'); box.className=`driver-benchmark aud${platformAudienceKey}`;
  box.innerHTML=`<div class="eyebrow">Overall platform reach in selected audience</div><div class="value">${reach===null?'n/a':reach.toFixed(0)+'%'}</div><div class="note">${platformLabel(field)} · users n=${users.length.toLocaleString()} · eligible n=${universe.length.toLocaleString()}</div>${compareOn?`<div class="driver-active-note ${platformAudienceKey}">Analyzing Audience ${platformAudienceKey}</div>`:''}`;
  toolbar.appendChild(box); viz.appendChild(toolbar);
  const explain=document.createElement('p'); explain.className='platform-note';
  explain.innerHTML='<b>Each row shows platform reach within that segment.</b> Index 100 means the segment reach matches the overall selected-audience reach. Above 100 = stronger reach in that segment; below 100 = weaker reach. ▲ / ▼ indicates a significant difference at 95%. Platform audiences overlap because respondents could select more than one platform.';
  viz.appendChild(explain);
  const head=document.createElement('div'); head.className='driver-headrow'; head.innerHTML='<div>Audience segment</div><div>Platform reach vs overall benchmark</div><div>Segment reach</div><div>Index</div><div>Users n</div>'; viz.appendChild(head);
  const list=document.createElement('div'); list.className='driver-list';
  const groups=dim.cats.map(([key,label])=>({key,label,st:platformProfileStat(universe,users,dim,key)}));
  groups.forEach(g=>{ const st=g.st,row=document.createElement('div'); row.className='driver-row'+(st.segmentN>0?' clickable':' unavailable'); const dir=st.idx===null?'':(st.idx>=100?'high':'low');
    row.innerHTML=`<div class="driver-label">${g.label}</div><div class="driver-track"><div class="bench" style="width:${Math.min(100,st.benchmarkPct||0)}%"></div><div class="rate" style="width:${Math.min(100,st.reachPct||0)}%"></div></div><div class="driver-rate">${st.reachPct===null?'N/A':st.reachPct.toFixed(0)+'%'}</div><div class="driver-index ${dir}">${st.idx===null?'—':'idx '+st.idx}${st.sig?(st.idx>=100?' ▲':' ▼'):''}</div><div class="driver-n">${st.segmentN>0?'n='+st.userN.toLocaleString():'—'}</div>`;
    row.title=st.segmentN>0 ? `${g.label}: ${st.reachPct.toFixed(1)}% use ${platformLabel(field)}; overall selected-audience reach ${st.benchmarkPct===null?'n/a':st.benchmarkPct.toFixed(1)+'%'}; index ${st.idx??'n/a'}; users n=${st.userN}; segment eligible n=${st.segmentN}` : (currentLang==='vi'?'Nền tảng này không khả dụng/không được hỏi tại thị trường này.':'This platform is not available / was not asked in this market.');
    if(st.segmentN>0) row.onclick=()=>{ showDrilldown(st.segmentUsers,st.segmentUniverse,`${platformLabel(field)} reach · ${g.label}`,false); }; list.appendChild(row); });
  viz.appendChild(list);
  document.getElementById('panelFootnote').textContent=`Base: respondents in the current ${compareOn?('Audience '+platformAudienceKey):'selected audience'} with a valid Platforms for news response. Overall ${platformLabel(field)} reach = ${reach===null?'n/a':reach.toFixed(0)+'%'} (${users.length.toLocaleString()}/${universe.length.toLocaleString()}). Each row uses that segment's eligible respondents as its denominator. Multi-select question; platform audiences overlap.`;
}
function renderPlatformMatrixModule(rowsA,rowsB){
  const viz=document.getElementById('vizArea');
  const rows=platformAudienceRows(rowsA,rowsB), dim=platformDim(platformMatrixDimKey);
  const toolbar=document.createElement('div'); toolbar.className='driver-toolbar';
  platformAudienceToggle(toolbar);
  toolbar.appendChild(driverSelect('Audience dimension',platformMatrixDimKey,PLATFORM_DIMS,v=>{platformMatrixDimKey=v;render();}));
  const box=document.createElement('div'); box.className=`driver-benchmark aud${platformAudienceKey}`;
  box.innerHTML=`<div class="eyebrow">How to read</div><div class="note"><b>Index 100</b> = platform reach in the segment matches overall selected-audience reach. Higher values show stronger reach; lower values show weaker reach. Hover a column header for the overall platform reach.</div>${compareOn?`<div class="driver-active-note ${platformAudienceKey}">Analyzing Audience ${platformAudienceKey}</div>`:''}`;
  toolbar.appendChild(box); viz.appendChild(toolbar);
  const note=document.createElement('p'); note.className='platform-note'; note.textContent='Each cell shows the share of that audience segment using the platform. This matrix compares individual platforms reported as sources for news content; platform audiences overlap.'; viz.appendChild(note);
  const pdata=PLATFORM_FIELDS.map(([field,label])=>{const universe=platformUniverse(rows,field), users=platformUsers(rows,field);return {field,label,universe,users,reach:universe.length?users.length/universe.length*100:null};}).filter(p=>p.universe.length>0 && p.users.length>0).sort((a,b)=>(b.reach||0)-(a.reach||0));
  const wrap=document.createElement('div'); wrap.className='driver-matrix-wrap'; const table=document.createElement('table'); table.className='driver-matrix platform-matrix';
  const thead=document.createElement('thead'),hr=document.createElement('tr'); hr.innerHTML='<th>Audience segment</th>'+pdata.map(p=>`<th title="${p.label}: ${(p.reach||0).toFixed(1)}% overall selected-audience reach; users n=${p.users.length}; eligible n=${p.universe.length}">${p.label}<span class="platform-reach">Overall ${(p.reach||0).toFixed(0)}% · n=${p.users.length}</span></th>`).join(''); thead.appendChild(hr); table.appendChild(thead);
  const tbody=document.createElement('tbody');
  dim.cats.forEach(([catKey,catLabel])=>{ const universeAny=rows.filter(r=>dim.test(r,catKey)).length; if(!universeAny)return; const tr=document.createElement('tr'),name=document.createElement('td');name.textContent=catLabel;tr.appendChild(name);
    pdata.forEach(p=>{const st=platformProfileStat(p.universe,p.users,dim,catKey),td=document.createElement('td');const c=st.idx===null?'neutral':(st.idx>=110?'high':st.idx<=90?'low':'neutral');td.className=`driver-cell ${c}${st.sig?' sig':''}${st.userN<30?' smallbase':''}`;td.innerHTML=`<div class="idx">${st.idx===null?'—':st.idx}${st.sig?(st.idx>=100?' ▲':' ▼'):''}</div><div class="pct">${st.reachPct===null?'n/a':st.reachPct.toFixed(0)+'%'} · n=${st.userN}</div>`;td.title=`${p.label} · ${catLabel}: ${st.reachPct===null?'n/a':st.reachPct.toFixed(1)+'%'} segment reach; overall benchmark ${st.benchmarkPct===null?'n/a':st.benchmarkPct.toFixed(1)+'%'}; index ${st.idx??'n/a'}; users n=${st.userN}; segment eligible n=${st.segmentN}`;td.onclick=()=>{showDrilldown(st.segmentUsers,st.segmentUniverse,`${p.label} reach · ${catLabel}`,false);};tr.appendChild(td);});tbody.appendChild(tr); });
  table.appendChild(tbody);wrap.appendChild(table);viz.appendChild(wrap);
  const lg=document.createElement('div');lg.className='driver-legend';lg.innerHTML='<span><i style="background:rgba(49,104,170,.21)"></i>Stronger reach</span><span><i style="background:rgba(196,65,51,.17)"></i>Weaker reach</span><span>▲ / ▼ = significant at 95%</span><span>Faded = segment platform users n &lt; 30</span>';viz.appendChild(lg);
  document.getElementById('panelFootnote').textContent=`Matrix uses the current ${compareOn?('Audience '+platformAudienceKey):'selected audience'} filters. Cell percentages are platform reach within each segment; compare them with the overall reach shown in each column header.`;
}

const DRIVER_DIMS = [
  { key:'country', label:'Country', cats:[['AU','Australia'],['CA','Canada'],['CN','China'],['FR','France'],['IN','India'],['KR','South Korea'],['SG','Singapore'],['UK','United Kingdom'],['US','United States']], test:(r,k)=>val(r,'country')===k },
  { key:'age', label:'Age', cats:[['18-24','18–24'],['25-34','25–34'],['35-44','35–44'],['45-54','45–54']], test:(r,k)=>val(r,'age')===k },
  { key:'gender', label:'Gender', cats:[['M','Male'],['F','Female']], test:(r,k)=>val(r,'gender')===k },
  { key:'income', label:'Household income', cats:[['L','Lower income'],['M','Middle income'],['H','Higher income']], test:(r,k)=>val(r,'income')===k },
  { key:'urbanicity', label:'Where they live', cats:[['capital','Capital city'],['hub','Major economic hub'],['other','Other city/town']], test:(r,k)=>val(r,'s2_urbanicity')===k },
  { key:'english', label:'English proficiency', cats:[['yes','Comfortable using English'],['no','Lower English comfort']], test:(r,k)=>k==='yes'?val(r,'s6_comfort_top2')===1:val(r,'s6_comfort_top2')===0 },
  { key:'connection', label:'Personal connection to Vietnam', cats:[['yes','Has personal connection'],['no','No personal connection']], test:(r,k)=>k==='yes'?val(r,'conn')===1:val(r,'conn')===0 },
  { key:'origin', label:'Vietnam origin', cats:[['yes','Vietnam origin (born/family)'],['no','No Vietnam origin']], test:(r,k)=>k==='yes'?val(r,'origin')===1:val(r,'origin')===0 },
  { key:'travelled', label:'Travelled to Vietnam', cats:[['yes','Has travelled to Vietnam'],['no','Has not travelled to Vietnam']], test:(r,k)=>k==='yes'?val(r,'traveled_vietnam')===1:val(r,'traveled_vietnam')===0 },
  { key:'visitintent', label:'Near-term visit intent', cats:[['yes','Plans to visit within 3 years'],['no','No near-term visit intent']], test:(r,k)=>k==='yes'?val(r,'visit_nearterm')===1:val(r,'visit_nearterm')===0 },
  { key:'familiarity', label:'Familiarity with Vietnam', cats:[['alot','Know a lot'],['fair','Know a fair amount'],['little','Know very little'],['nameonly','Only heard of it by name']], test:(r,k)=>val(r,'d1_familiarity')===k },
  { key:'segment', label:'Audience mindset', cats:[['enthusiasts','Vietnam Enthusiasts'],['explorers','Global Explorers'],['loyalists','Vietnam Focused'],['disengaged','Disengaged']], test:(r,k)=>val(r,'segment')===k },
  { key:'influencer', label:'Influencer profile', cats:[['yes','Influencer profile'],['no','Not influencer profile']], test:(r,k)=>k==='yes'?val(r,'infl')===1:val(r,'infl')===0 }
];

function driverMetric(key){ return DRIVER_METRICS.find(x=>x.key===key) || DRIVER_METRICS[0]; }
function driverDim(key){ return DRIVER_DIMS.find(x=>x.key===key) || DRIVER_DIMS[0]; }
function driverStat(rows, metric){
  const elig=rows.filter(metric.eligible); const count=elig.filter(metric.success).length;
  return { n:elig.length, count, rate:elig.length?count/elig.length*100:null, elig };
}
function driverCellStat(universeRows, subgroupRows, metric){
  const u=driverStat(universeRows,metric), s=driverStat(subgroupRows,metric);
  const idx=(s.rate!==null && u.rate && u.rate>0)?Math.round(s.rate/u.rate*100):null;
  const sig=(s.n>0 && u.n>s.n)?computeIndexSig(s.n,s.count,u.n,u.count).sig:false;
  return { ...s, benchmark:u.rate, benchmarkN:u.n, idx, sig };
}
function driverRowsForDim(rows, dim){
  return dim.cats.map(([key,label])=>({key,label,rows:rows.filter(r=>dim.test(r,key))})).filter(x=>x.rows.length>0);
}
function driverAudienceRows(rowsA, rowsB){
  if(!compareOn) { driverAudienceKey='A'; return rowsA; }
  return driverAudienceKey==='B' ? rowsB : rowsA;
}
function driverAudienceToggle(container){
  if(!compareOn) return;
  const ctl=document.createElement('div'); ctl.className='driver-control';
  ctl.innerHTML='<label>Analyze audience</label>';
  const wrap=document.createElement('div'); wrap.className='driver-audtoggle';
  ['A','B'].forEach(k=>{
    const b=document.createElement('button');
    b.type='button';
    b.className=`driver-audbtn ${driverAudienceKey===k?'active '+k:''}`;
    b.textContent=`Audience ${k}`;
    b.setAttribute('aria-pressed', driverAudienceKey===k ? 'true' : 'false');
    b.onclick=(e)=>{ e.preventDefault(); e.stopPropagation(); driverAudienceKey=k; render(); };
    wrap.appendChild(b);
  });
  ctl.appendChild(wrap); container.appendChild(ctl);
}
function driverSelect(label, value, options, onChange){
  const ctl=document.createElement('div'); ctl.className='driver-control';
  const lab=document.createElement('label'); lab.textContent=label; ctl.appendChild(lab);
  const sel=document.createElement('select');
  options.forEach(o=>{const op=document.createElement('option'); op.value=o.key; op.textContent=o.label; op.selected=o.key===value; sel.appendChild(op);});
  sel.onchange=()=>onChange(sel.value); ctl.appendChild(sel); return ctl;
}
function renderDriversModule(rowsA, rowsB){
  const viz=document.getElementById('vizArea');
  const rows=driverAudienceRows(rowsA,rowsB), metric=driverMetric(driverMetricKey), dim=driverDim(driverDimKey);
  const toolbar=document.createElement('div'); toolbar.className='driver-toolbar';
  driverAudienceToggle(toolbar);
  toolbar.appendChild(driverSelect('Performance measure',driverMetricKey,DRIVER_METRICS,v=>{driverMetricKey=v;render();}));
  toolbar.appendChild(driverSelect('Audience dimension',driverDimKey,DRIVER_DIMS,v=>{driverDimKey=v;render();}));
  const bench=driverStat(rows,metric); const box=document.createElement('div'); box.className=`driver-benchmark aud${driverAudienceKey}`;
  box.innerHTML=`<div class="eyebrow">Selected audience benchmark</div><div class="value">${bench.rate===null?'n/a':bench.rate.toFixed(0)+'%'}</div><div class="note">${metric.label} · eligible n=${bench.n.toLocaleString()}</div>${compareOn?`<div class="driver-active-note ${driverAudienceKey}">Analyzing Audience ${driverAudienceKey}</div>`:''}`;
  toolbar.appendChild(box); viz.appendChild(toolbar);
  const explain=document.createElement('p'); explain.className='driver-explain'; explain.innerHTML=(compareOn?'<b>Audience A and B are analyzed separately.</b> Use the audience switch above to change the benchmark and results. ':'')+'<b>Index 100</b> = same as the selected-audience benchmark. Above 100 = more likely; below 100 = less likely. ▲ / ▼ indicates a statistically significant difference from the rest of the selected audience at 95% confidence. Click a result to profile the people behind it.'; viz.appendChild(explain);
  const head=document.createElement('div'); head.className='driver-headrow'; head.innerHTML='<div>Group</div><div>Performance vs benchmark</div><div>Result</div><div>Index</div><div>Eligible n</div>'; viz.appendChild(head);
  const list=document.createElement('div'); list.className='driver-list';
  const groups=driverRowsForDim(rows,dim).map(g=>({...g, stat:driverCellStat(rows,g.rows,metric)}));
  groups.forEach(g=>{
    const st=g.stat; const row=document.createElement('div'); row.className='driver-row clickable';
    const maxPct=100; const rate=st.rate||0, bm=st.benchmark||0; const dir=st.idx===null?'':(st.idx>=100?'high':'low');
    row.innerHTML=`<div class="driver-label">${g.label}</div><div class="driver-track"><div class="bench" style="width:${Math.min(100,bm)}%"></div><div class="rate" style="width:${Math.min(100,rate)}%"></div></div><div class="driver-rate">${st.rate===null?'n/a':st.rate.toFixed(0)+'%'}</div><div class="driver-index ${dir}">${st.idx===null?'idx n/a':'idx '+st.idx}${st.sig?(st.idx>=100?' ▲':' ▼'):''}</div><div class="driver-n">n=${st.n.toLocaleString()}</div>`;
    row.title=`${g.label}: ${st.rate===null?'n/a':st.rate.toFixed(1)+'%'}; benchmark ${st.benchmark===null?'n/a':st.benchmark.toFixed(1)+'%'}; index ${st.idx??'n/a'}; eligible n=${st.n}`;
    row.onclick=()=>{ const elig=g.rows.filter(metric.eligible); const successes=elig.filter(metric.success); showDrilldown(successes, rows.filter(metric.eligible), `${metric.label} · ${g.label}`, false); };
    list.appendChild(row);
  });
  viz.appendChild(list);
  document.getElementById('panelFootnote').textContent=`Analysis uses the current ${compareOn?('Audience '+driverAudienceKey):'selected audience'} filters. Small eligible bases should be read cautiously.`;
}
function renderDriverMatrixModule(rowsA, rowsB){
  const viz=document.getElementById('vizArea');
  const rows=driverAudienceRows(rowsA,rowsB), dim=driverDim(driverMatrixDimKey);
  const toolbar=document.createElement('div'); toolbar.className='driver-toolbar';
  driverAudienceToggle(toolbar);
  toolbar.appendChild(driverSelect('Audience dimension',driverMatrixDimKey,DRIVER_DIMS,v=>{driverMatrixDimKey=v;render();}));
  const box=document.createElement('div'); box.className=`driver-benchmark aud${driverAudienceKey}`; box.innerHTML=`<div class="eyebrow">How to read</div><div class="note"><b>Index</b> compares each group with the selected audience. Hover or click any cell for the raw percentage, base and demographic profile.</div>${compareOn?`<div class="driver-active-note ${driverAudienceKey}">Analyzing Audience ${driverAudienceKey}</div>`:''}`; toolbar.appendChild(box); viz.appendChild(toolbar);
  const wrap=document.createElement('div'); wrap.className='driver-matrix-wrap'; const table=document.createElement('table'); table.className='driver-matrix';
  const totals={}; DRIVER_METRICS.forEach(m=>totals[m.key]=driverStat(rows,m));
  const thead=document.createElement('thead'); const hr=document.createElement('tr');
  hr.innerHTML='<th>Audience group</th>'+DRIVER_METRICS.map(m=>`<th class="driver-metric-head">${m.label}<span class="bench">Benchmark ${totals[m.key].rate===null?'n/a':totals[m.key].rate.toFixed(0)+'%'} · n=${totals[m.key].n}</span></th>`).join(''); thead.appendChild(hr); table.appendChild(thead);
  const tbody=document.createElement('tbody');
  driverRowsForDim(rows,dim).forEach(g=>{
    const tr=document.createElement('tr'); const name=document.createElement('td'); name.textContent=g.label; tr.appendChild(name);
    DRIVER_METRICS.forEach(m=>{ const st=driverCellStat(rows,g.rows,m); const td=document.createElement('td'); const c=st.idx===null?'neutral':(st.idx>=110?'high':(st.idx<=90?'low':'neutral')); td.className=`driver-cell ${c}${st.sig?' sig':''}${st.n<30?' smallbase':''}`;
      td.innerHTML=`<div class="idx">${st.idx===null?'—':st.idx}${st.sig?(st.idx>=100?' ▲':' ▼'):''}</div><div class="pct">${st.rate===null?'n/a':st.rate.toFixed(0)+'%'} · n=${st.n}</div>`;
      td.title=`${g.label} · ${m.label}: ${st.rate===null?'n/a':st.rate.toFixed(1)+'%'}; benchmark ${st.benchmark===null?'n/a':st.benchmark.toFixed(1)+'%'}; index ${st.idx??'n/a'}; eligible n=${st.n}`;
      td.onclick=()=>{ const elig=g.rows.filter(m.eligible); const successes=elig.filter(m.success); showDrilldown(successes, rows.filter(m.eligible), `${m.label} · ${g.label}`, false); }; tr.appendChild(td); });
    tbody.appendChild(tr);
  }); table.appendChild(tbody); wrap.appendChild(table); viz.appendChild(wrap);
  const lg=document.createElement('div'); lg.className='driver-legend'; lg.innerHTML='<span><i style="background:rgba(49,104,170,.21)"></i>Higher index</span><span><i style="background:rgba(196,65,51,.17)"></i>Lower index</span><span>▲ / ▼ = significant at 95%</span><span>Faded cell = eligible n &lt; 30</span>'; viz.appendChild(lg);
  document.getElementById('panelFootnote').textContent=`Matrix uses the current ${compareOn?('Audience '+driverAudienceKey):'selected audience'} filters. Different performance measures have different eligible bases.`;
}

function renderScreenerModule(mod) {
  const vizArea = document.getElementById('vizArea');
  if (mod.type === 'screenerfullscale') { renderScreenerFullScale(mod); return; }
  if (mod.type === 'funnel') {
    if (screenerCompareOn || screenerTargetA.base === 'completes') {
      const p = document.createElement('p');
      p.className = 'desc';
      p.textContent = 'This table only applies to a single "All respondents" target, since it shows how the screener funnelled down to completes. Turn off the second target and set Target A\u2019s base to "All respondents" to see it.';
      vizArea.appendChild(p);
      return;
    }
    const table = document.createElement('table');
    table.className = 'heat';
    let head = '<thead><tr><th class="rowhead">Market</th><th>Total responses</th><th>Final complete</th><th>Incidence %</th></tr></thead>';
    let body = '<tbody>';
    SCREENER.order.forEach(code => {
      const b = SCREENER.base_n[code];
      const pct = b ? (b.complete/b.total*100).toFixed(1) : 'n/a';
      body += `<tr><td class="rowhead">${SCREENER.names[code]}</td><td>${b.total}</td><td>${b.complete}</td><td>${pct}%</td></tr>`;
    });
    body += '</tbody>';
    table.innerHTML = head + body;
    vizArea.appendChild(table);
    return;
  }

  const itemLabels = mod.dataKey ? Object.keys(SCREENER[mod.dataKey]) : Object.keys(mod.fieldMap);
  let vals = itemLabels.map(item => ({
    label: item,
    a: screenerValue(mod, screenerTargetA, item),
    b: screenerCompareOn ? screenerValue(mod, screenerTargetB, item) : null,
  }));
  vals.sort((x,y) => (y.a||0)-(x.a||0));
  const maxV = 100; // fixed 0-100% basis, not relative to the largest value in view
  vals.forEach(v => {
    const row = document.createElement('div'); row.className='barrow';
    if (screenerCompareOn) {
      let sig = false;
      if (screenerTargetA.base==='completes' && screenerTargetB.base==='completes' && mod.fieldMap) {
        const field = mod.fieldMap[v.label];
        const rowsForTarget = t => t.country==='TOTAL' ? ROWS : ROWS.filter(r=>val(r,'country')===t.country);
        const cA = flagCount(rowsForTarget(screenerTargetA), field), cB = flagCount(rowsForTarget(screenerTargetB), field);
        sig = twoPropSig(cA.count, cA.n, cB.count, cB.n);
      }
      row.innerHTML = `<div class="barlabel">${(mod.displayMap && mod.displayMap[v.label]) || v.label}</div>
        <div class="bartrack">
          <div class="barfillA" style="width:${(v.a/maxV*100).toFixed(1)}%"></div>
          <div class="barfillB" style="width:${(v.b/maxV*100).toFixed(1)}%"></div>
        </div>
        <div class="barval"><div class="cmpvals"><span class="vA">A ${v.a!==null?v.a.toFixed(0)+'%':'n/a'}</span><span class="vB">B ${v.b!==null?v.b.toFixed(0)+'%':'n/a'}</span></div>${sigSuffix(sig, v.a, v.b, 'Significant difference between Target A and Target B, 95% confidence (only calculable when both use Completed interviews)')}</div>`;
    } else {
      row.innerHTML = `<div class="barlabel">${(mod.displayMap && mod.displayMap[v.label]) || v.label}</div>
        <div class="bartrack"><div class="barfillSingle" style="width:${(v.a/maxV*100).toFixed(1)}%"></div></div>
        <div class="barval">${v.a!==null&&v.a!==undefined?v.a.toFixed(1)+'%':'n/a'}</div>`;
      if (mod.fieldMap) {
        const field = mod.fieldMap[v.label];
        if (screenerTargetA.base === 'completes') {
          const baseRows = screenerTargetA.country === 'TOTAL' ? ROWS : ROWS.filter(r => val(r,'country')===screenerTargetA.country);
          makeClickable(row, eligibleRows(baseRows, field), r => val(r, field) === 1, v.label);
        } else {
          const baseRows = screenerTargetA.country === 'TOTAL' ? SCREENER_ROWS : SCREENER_ROWS.filter(r => sval(r,'country')===screenerTargetA.country);
          makeClickable(row, eligibleRows(baseRows, field, sval), r => sval(r, field) === 1, v.label, true);
        }
      }
    }
    vizArea.appendChild(row);
  });
  document.getElementById('panelFootnote').textContent = screenerCompareOn
    ? `Target A: ${screenerTargetLabel(screenerTargetA)}  ·  Target B: ${screenerTargetLabel(screenerTargetB)}`
    : `Base | ${screenerTargetLabel(screenerTargetA)}. Click any bar to see its demographic profile below.`;
}


function pct1(v) { return v===null || v===undefined ? null : Math.round(v*10)/10; }
function fieldBase(rows, field) {
  let n=0; rows.forEach(r=>{ const v=val(r,field); if(v===0 || v===1) n++; }); return n;
}
function topFlags(rows, fields, limit) {
  return fields.map(([field,label])=>({field,label,pct:pctFlag(rows,field),n:fieldBase(rows,field)}))
    .filter(x=>x.pct!==null).sort((a,b)=>b.pct-a.pct).slice(0,limit||3);
}
function topCategory(rows, field) {
  const d=catDist(rows,field); const labels=CAT_LABELS[field]||{};
  const entries=Object.entries(d.dist).sort((a,b)=>b[1]-a[1]);
  if(!entries.length) return null;
  return {label:labels[entries[0][0]]||entries[0][0], pct:entries[0][1], n:d.n};
}
function topCategoriesAdaptive(rows, field, gapThreshold) {
  const d=catDist(rows,field); const labels=CAT_LABELS[field]||{};
  const entries=Object.entries(d.dist).sort((a,b)=>b[1]-a[1]);
  if(!entries.length) return [];
  const out=[{label:labels[entries[0][0]]||entries[0][0], pct:entries[0][1], n:d.n}];
  if(entries.length>1 && (entries[0][1]-entries[1][1]) <= (gapThreshold ?? 5)) {
    out.push({label:labels[entries[1][0]]||entries[1][0], pct:entries[1][1], n:d.n});
  }
  return out;
}
function plannerRows(items) {
  if(!items || !items.length) return '<div class="planner-empty">No eligible responses for this audience.</div>';
  return '<div class="planner-list">'+items.map(x=>`<div class="planner-row"><span class="label" title="${x.label}">${x.label}</span><span class="value">${x.pct.toFixed(1)}%</span></div>`).join('')+'</div>';
}
function top2C15(rows) {
  let n=0, hit=0;
  rows.forEach(r=>{ const v=val(r,'c15'); if(v!==null && v!==undefined){ n++; if(v==='def_would'||v==='prob_would') hit++; } });
  return {pct:n?Math.round(hit/n*1000)/10:null,n};
}
function englishComfortTop2(rows) {
  const d=catDist(rows,'s6_comfort_cat');
  const pct=d.n ? ((d.dist.vc||0)+(d.dist.c||0)) : null;
  return {label:'Comfortable using English', pct, n:d.n};
}
function plannerProfile(rows, state, cls, audienceLabel) {
  const def=filterSummaryParts(state); const name=def.length?def.join(' · '):'All qualified respondents';
  const age=topCategoriesAdaptive(rows,'age',5), gender=topCategoriesAdaptive(rows,'gender',5), income=topCategoriesAdaptive(rows,'income',5);
  const englishComfort=englishComfortTop2(rows);
  const platforms=topFlags(rows, SECTIONS.devices_sources.modules.platforms.fields, 4);
  const sources=topFlags(rows, SECTIONS.devices_sources.modules.sources.fields, 3);
  const topics=topFlags(rows, SECTIONS.topics.modules.d3.fields, 4);
  const formats=topFlags(rows, SECTIONS.format_length.modules.fmtnews.fields, 4);
  const weekday=topFlags(rows, SECTIONS.viewing_time.modules.weekday.fields, 3);
  const weekend=topFlags(rows, SECTIONS.viewing_time.modules.weekend.fields, 2);
  const discovery=topFlags(rows, SECTIONS.vntd_nonaudience.modules.discovery_pref.fields, 3);
  const growth=topFlags(rows, SECTIONS.vntd_nonaudience.modules.likelihood.fields.filter(x=>x[0]!=='likely_nothing_particular'), 3);
  const barrierFields=[...SECTIONS.vntd_nonaudience.modules.barrier_aware.fields,...SECTIONS.vntd_nonaudience.modules.barrier_notinterested.fields];
  const barriers=topFlags(rows, barrierFields, 3);
  const watch=top2C15(rows);
  const viewer=pctFlag(rows,'vviewer'); const aware=pctFlag(rows,'vaware');
  const sampleWarn=rows.length<50?'Very small base — directional only':(rows.length<100?'Small base — interpret differences cautiously':'');
  const kpi=(obj,label)=>`<div class="planner-kpi"><strong>${obj&&obj.pct!==null?obj.pct.toFixed(1)+'%':'—'}</strong><span>${label}</span></div>`;
  const topText=(arr)=>arr&&arr.length?arr[0].label:'not enough data';
  return `<div class="planner-profile ${cls}">
    <div class="planner-head"><div class="planner-eyebrow">${audienceLabel}</div><div class="planner-name">${name}</div><div class="planner-base">Selected base: n = ${rows.length}${sampleWarn?' · '+sampleWarn:''}</div></div>
    <div class="planner-grid">
      <div class="planner-block full"><h4>Headline</h4><div class="planner-kpis">${kpi({pct:aware},'Aware of Vietnam Today')}${kpi({pct:viewer},'Has watched Vietnam Today')}${kpi(watch,'Would probably / definitely watch · eligible non-audience')}</div></div>
      <div class="planner-block"><h4>Who</h4>${plannerRows([...age,...gender,...income,...(englishComfort.pct!==null?[englishComfort]:[])])}<div class="planner-note">Shows the leading age, gender and within-market income groups, plus self-reported English comfort. When the top two demographic categories are within 5 percentage points, both are shown to avoid overstating a marginal lead.</div></div>
      <div class="planner-block"><h4>Reach · platforms</h4>${plannerRows(platforms)}<div class="planner-note">Online platforms used for news. Top news source: ${topText(sources)}.</div></div>
      <div class="planner-block"><h4>Content · Vietnam</h4>${plannerRows(topics)}<div class="planner-note">Topics this audience says it wants about Vietnam specifically.</div></div>
      <div class="planner-block"><h4>Format · news</h4>${plannerRows(formats)}<div class="planner-note">Preferred formats for news and factual updates.</div></div>
      <div class="planner-block"><h4>Timing · TV weekdays</h4>${plannerRows(weekday)}<div class="planner-note">Weekend peaks: ${weekend.length?weekend.map(x=>x.label+' '+x.pct.toFixed(1)+'%').join(' · '):'not enough data'}.</div></div>
      <div class="planner-block"><h4>Discovery</h4>${plannerRows(discovery)}<div class="planner-note">Preferred routes for discovering Vietnam Today content among respondents asked these questions.</div></div>
      <div class="planner-block"><h4>Growth levers</h4>${plannerRows(growth)}<div class="planner-note">Factors respondents say would increase their likelihood to watch.</div></div>
      <div class="planner-block"><h4>Barriers</h4>${plannerRows(barriers)}<div class="planner-note">Barrier items come from different eligible subgroups; percentages should not be treated as a single common-base ranking.</div></div>
      <div class="planner-block full"><h4>Media planning read-out</h4><div class="planner-action">Prioritise <strong>${topText(platforms)}</strong> for distribution, lead with <strong>${topText(topics)}</strong> content, and package it primarily as <strong>${topText(formats)}</strong>. For TV scheduling, the strongest weekday window in this audience is <strong>${topText(weekday)}</strong>. Use the discovery and growth blocks above to shape acquisition activity rather than relying on channel awareness alone.</div></div>
    </div>
  </div>`;
}
function renderPlanner(rowsA, rowsB) {
  const area=document.getElementById('vizArea');
  area.innerHTML=`<div class="planner-wrap ${compareOn?'compare':''}">${plannerProfile(rowsA,filterA,'A','Audience 1')}${compareOn?plannerProfile(rowsB,filterB,'B','Audience 2'):''}</div>`;
  document.getElementById('panelFootnote').textContent='All figures are descriptive percentages within the selected audience. Bases vary where questions were asked only to eligible respondents; the barrier block explicitly combines items from different eligible subgroups.';
}

function render() {
  clearDrilldown();
  buildNav();
  const section = SECTIONS[currentSection];

  document.getElementById('filterbarWrap').style.display = section.isScreener ? 'none' : '';
  document.getElementById('toggleBWrap').style.display = section.isScreener ? 'none' : '';
  document.getElementById('screenerBar').style.display = section.isScreener ? '' : 'none';
  document.getElementById('screenerBarB').style.display = (section.isScreener && screenerCompareOn) ? '' : 'none';
  document.getElementById('screenerToggleBWrap').style.display = section.isScreener ? '' : 'none';

  let rowsA = [], rowsB = [];
  if (section.isScreener) {
    renderScreenerTargetPanel('A', screenerTargetA);
    if (screenerCompareOn) renderScreenerTargetPanel('B', screenerTargetB);
    document.getElementById('screenerToggleBBtn').className = 'toggleB' + (screenerCompareOn?' on':'');
    document.getElementById('screenerToggleBBtn').textContent = screenerCompareOn ? '✕ Remove second target' : '+ Compare with a second market or base';
    document.getElementById('totalN').textContent = ROWS.length;
  } else {
    buildFilterPanel('filtersA', filterA, 'A');
    document.getElementById('cardB').style.display = compareOn ? '' : 'none';
    if (compareOn) buildFilterPanel('filtersB', filterB, 'B');
    document.getElementById('toggleBBtn').className = 'toggleB' + (compareOn?' on':'');
    document.getElementById('toggleBBtn').textContent = compareOn ? '✕ Remove comparison audience' : '+ Add comparison audience';

    rowsA = filteredRows(filterA);
    rowsB = compareOn ? filteredRows(filterB) : [];
    document.getElementById('ncountA').textContent = `Selected base: n = ${rowsA.length}`;
    document.getElementById('ncountB').textContent = `Selected base: n = ${rowsB.length}`;
    document.getElementById('totalN').textContent = ROWS.length;
  }

  renderAudienceSummary(rowsA, rowsB, !!section.isScreener);
  decorateQuickviewIcons();
  if (!section.isScreener) setFiltersExpanded(filtersExpanded);

  document.getElementById('pageH2').textContent = section.label;
  const sectionDescriptions = {
    overview: '',
    planner: 'Build a concise profile of the selected audience across countries, demographics, reach, content, formats, timing and growth potential.',
    demographics_profile: 'Understand the audience’s demographic profile, connection to Vietnam, familiarity with Vietnam, English proficiency and perceptions of Vietnam.',
    audience_segments: 'Explore how audiences differ in openness to international media, worldview, content preferences and attitudes.',
    influential_audience: 'Identify business, investment, policy and media-related profiles, and understand their views of Vietnam.',
    devices_sources: 'See where the audience gets news and content, which devices and platforms they use, and how they access programmes.',
    platform_compare: 'Compare the demographic, relationship and influential profiles of users across media platforms to identify which platforms are best suited to each target audience. Use this together with Audience Drivers to identify both the priority audience and the platforms most likely to reach them.',
    viewing_time: 'Identify the strongest weekday and weekend time windows for reaching the selected audience on TV.',
    format_length: 'Understand preferred content formats, programme length, subtitle needs and language preferences.',
    topics: 'Identify the topics and editorial themes that are most relevant to the selected audience.',
    region_country: 'Understand which regions and countries attract the audience’s interest, and how Southeast Asia and Vietnam compare.',
    travel_context: 'Explore past travel, plans to visit Vietnam and near-term versus longer-term visit potential.',
    vietnam_news: 'Understand recent exposure to Vietnam-related news and content, and how the tone of that coverage is perceived.',
    international_channels: 'Benchmark Vietnam Today awareness against other international news channels.',
    vntd_funnel: 'Follow the Vietnam Today audience funnel from awareness to trial and recent viewing, and identify where conversion is strongest or weakest.',
    vntd_audience: 'Understand who Vietnam Today viewers are, what they value, how the channel helps them understand Vietnam, and their likelihood to continue watching or recommend it.',
    vntd_nonaudience: 'Identify why non-viewers do not watch, what would increase their likelihood to watch, and the best routes for access and discovery.',
    social_eval: 'Compare audience response to tested social media content and identify which groups respond most positively.',
    audience_drivers: 'Identify which audience characteristics are associated with stronger Vietnam Today performance and where the strongest targeting opportunities lie.',
    screener: 'Review the survey base, wider population interest in regions, and interest in Vietnam.'
  };
  document.getElementById('pageP').textContent = sectionDescriptions[currentSection] || '';

  const modTabs = document.getElementById('moduleTabs');
  modTabs.innerHTML = '';
  Object.keys(section.modules).forEach(mk => {
    const tab = document.createElement('div');
    tab.className = 'mtab' + (mk===currentModule ? ' active':'');
    tab.innerHTML = `<span class="tabicon">${section.icon || ''}</span><span>${section.modules[mk].label}</span>`;
    tab.onclick = () => { currentModule = mk; render(); };
    modTabs.appendChild(tab);
  });

  const mod = section.modules[currentModule];
  document.getElementById('panelTitle').textContent = mod.label;
  document.getElementById('panelDesc').textContent = mod.desc || '';
  const isSnapshot = currentSection === 'overview';
  modTabs.style.display = isSnapshot ? 'none' : '';
  document.getElementById('panelTitle').style.display = isSnapshot ? 'none' : '';
  document.getElementById('panelDesc').style.display = isSnapshot ? 'none' : '';
  const brandMark=document.getElementById('brandMark');
  if (brandMark) brandMark.classList.toggle('is-hidden', !(currentSection==='vntd_funnel' || currentSection==='vntd_audience' || currentSection==='vntd_nonaudience' || currentSection==='social_eval' || currentSection==='audience_drivers')); 
  const vizArea = document.getElementById('vizArea');
  vizArea.innerHTML = '';
  document.body.classList.toggle('snapshot-view', isSnapshot);
  vizArea.classList.toggle('compare-mode', compareOn && !section.isScreener);
  vizArea.classList.toggle('media-list-wide', !section.isScreener && mod.field === 'access');
  document.getElementById('panelFootnote').textContent = '';
  const compareBarTypes = new Set(['flags','categorical','visitintent','sentiment','scalebar','recallbar','nps','vntdtouchpoints']);
  if (compareOn && compareBarTypes.has(mod.type)) {
    const lg=document.createElement('div'); lg.className='compare-legend';
    lg.innerHTML='<span><i style="background:var(--lineA)"></i>Audience A</span><span><i style="background:var(--lineB)"></i>Audience B</span><span style="margin-left:4px;color:var(--text-muted)">▲ = significantly higher (95%)</span>';
    vizArea.appendChild(lg);
  }

  if (section.isScreener) renderScreenerModule(mod);
  else if (mod.type === 'planner') renderPlanner(rowsA, rowsB);
  else if (mod.type === 'kpi') renderKPIs(rowsA, rowsB);
  else if (mod.type === 'vntdfunnel') renderVntdFunnel(rowsA, rowsB);
  else if (mod.type === 'viewerprofile') renderViewerProfileModule(mod, rowsA, rowsB);
  else if (mod.type === 'vntdtouchpoints') renderVntdTouchpointsModule(mod, rowsA, rowsB);
  else if (mod.type === 'flags') renderFlagsModule(mod, rowsA, rowsB);
  else if (mod.type === 'socialpost') renderSocialPostModule(mod, rowsA, rowsB);
  else if (mod.type === 'a2topics') renderA2TopicsModule(mod, rowsA, rowsB);
  else if (mod.type === 'categorical') renderCategoricalModule(mod, rowsA, rowsB);
  else if (mod.type === 'visitintent') renderVisitIntentModule(mod, rowsA, rowsB);
  else if (mod.type === 'sentiment') renderSentimentModule(mod, rowsA, rowsB);
  else if (mod.type === 'scalebar') renderScaleBarModule(mod, rowsA, rowsB);
  else if (mod.type === 'recallbar') renderRecallModule(mod, rowsA, rowsB);
  else if (mod.type === 'nps') renderNPSModule(mod, rowsA, rowsB);
  else if (mod.type === 'segments2x2') renderSegmentModule(mod, rowsA, rowsB);
  else if (mod.type === 'fullscale') renderFullScaleModule(mod, rowsA, rowsB);
  else if (mod.type === 'coveragebar') renderCoverageBarModule(mod, rowsA, rowsB);
  else if (mod.type === 'agreementscale') renderAgreementScaleModule(mod, rowsA, rowsB);
  else if (mod.type === 'topicscompare') renderTopicsCompareModule(rowsA);
  else if (mod.type === 'curve') renderCurveModule(mod, rowsA, rowsB);
  else if (mod.type === 'drivers') renderDriversModule(rowsA, rowsB);
  else if (mod.type === 'drivermatrix') renderDriverMatrixModule(rowsA, rowsB);
  else if (mod.type === 'platformprofile') renderPlatformProfileModule(rowsA, rowsB);
  else if (mod.type === 'platformmatrix') renderPlatformMatrixModule(rowsA, rowsB);
  applyLanguage(currentLang);
}


