function i18nTranslateText(raw) {
  if (currentLang !== 'vi' || raw === null || raw === undefined) return raw;
  const s = String(raw), m = s.match(/^(\s*)(.*?)(\s*)$/s), core = m ? m[2] : s;
  if (I18N_VI[core]) return (m?m[1]:'') + I18N_VI[core] + (m?m[3]:'');
  // Translate reviewed phrases inside dynamic labels while preserving numbers and punctuation.
  const dynamicKeys = ['Selected group','Selected base: n =','Selected base:','Audience 1','Audience 2','Audience A','Audience B','Target A','Target B','Answer n','Base n','All qualified respondents','Completed interviews only','All respondents','all respondents','completes only','Aware of Vietnam Today','Has watched Vietnam Today','Watched within past week','Significance:','A higher','B higher','responses','completes','Base'];
  let out = core;
  dynamicKeys.forEach(k=>{ if(I18N_VI[k]) out = out.split(k).join(I18N_VI[k]); });
  // Handle recurrent dynamic explanatory strings that contain live values.
  out = out.replace(/^n = ([\d,.]+) người tham gia, ([\d,.]+) bài hoàn thành$/, 'n = $1 người tham gia, $2 bài hoàn thành');
  out = out.replace(/^Weekend peaks:/, 'Khung giờ nổi bật cuối tuần:');
  out = out.replace(/^Online platforms used for news\. Top news source:/, 'Nền tảng trực tuyến dùng để theo dõi tin tức. Nguồn tin hàng đầu:');
  out = out.replace(/^Showing /, 'Đang hiển thị ');
  out = out.replace(/^Based on /, 'Dựa trên ');
  out = out.replace(/^Base \|/, 'Số mẫu |');
  return (m?m[1]:'') + out + (m?m[3]:'');
}
