function i18nTranslateNode(node) {
  if (!node) return;
  if (node.nodeType === Node.TEXT_NODE) {
    if (node.__i18nEn === undefined) node.__i18nEn = node.nodeValue;
    node.nodeValue = currentLang === 'vi' ? i18nTranslateText(node.__i18nEn) : node.__i18nEn;
    return;
  }
  if (node.nodeType !== Node.ELEMENT_NODE || node.tagName==='SCRIPT' || node.tagName==='STYLE') return;
  if (!node.__i18nAttrs) node.__i18nAttrs = {};
  ['title','placeholder','aria-label'].forEach(a=>{
    if (node.hasAttribute && node.hasAttribute(a)) {
      if (!(a in node.__i18nAttrs)) node.__i18nAttrs[a] = node.getAttribute(a);
      node.setAttribute(a, currentLang==='vi' ? i18nTranslateText(node.__i18nAttrs[a]) : node.__i18nAttrs[a]);
    }
  });
  Array.from(node.childNodes || []).forEach(i18nTranslateNode);
}

